(function () {
  'use strict';
  const E=window.CBEngine,D=window.CBData,KEY='cloudbridge-workspace-v1';
  const clone=x=>structuredClone(x), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=n=>new Intl.NumberFormat('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(n)||0);
  const integer=n=>new Intl.NumberFormat('zh-CN',{maximumFractionDigits:0}).format(Number(n)||0);
  const pct=n=>new Intl.NumberFormat('zh-CN',{maximumFractionDigits:2}).format(n)+'%';
  const now=()=>new Date().toLocaleString('sv-SE',{timeZone:'Asia/Shanghai'}).slice(0,16);
  function fresh(){return {version:1,apps:clone(D.apps),selected:D.apps[0].id,model:clone(D.model),draftModel:clone(D.model),modelHistory:[{at:'2026-10-26 09:00',text:'DEMO-1.0 初始化'}],view:'underwriting'};}
  let state;
  try { const raw=JSON.parse(localStorage.getItem(KEY)); state=raw?.version===1&&raw.apps?.length&&raw.model?raw:fresh(); } catch {state=fresh();}
  const views=['application','underwriting','claim','assessment','model'];
  const ui={view:views.includes(state.view)?state.view:'underwriting',formStep:0,uwTab:'risk',claimTab:'report',reviewTab:'monitor',mapModule:'m1',region:null,modelTab:'parameters',m2Layer:'hazard',m2Basis:'standard',m2Configuration:'regional',m2Service:null};
  if(location.hash==='#m2'){ui.view='underwriting';ui.mapModule='m2';}
  const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
  const app=()=>state.apps.find(x=>x.id===state.selected)||state.apps[0];
  const quote=(a=app(),m=state.model)=>E.quote(a,m,D.regions);
  const policyTerms=()=>app().policy?.terms||app();
  const claim=()=>app().claim;
  const assessment=()=>claim().approved&&claim().settlement?.assessment?claim().settlement.assessment:E.assess(app(),claim());
  const audit=text=>app().history.unshift({at:now(),text});
  function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('浏览器存储不可用，当前更改仅保留在本次会话');}}
  function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),3400);}
  const paths={
    shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3Z M8 12l3 3 5-6',
    form:'M8 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V9L15 3H8Z M14 3v7h7 M7 14h8 M7 17h6',
    globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z M3 12h18 M12 3c-5 5-5 13 0 18 5-5 5-13 0-18Z',
    claim:'M8 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-3 M7 8h5 M7 12h3 M14 10l6-6 3 3-6 6-4 1 1-4Z',
    scan:'M4 8V4h4 M16 4h4v4 M20 16v4h-4 M8 20H4v-4 M4 12h16 M8 9v6 M12 9v6 M16 9v6',
    model:'M4 19h16 M6 15v-3 M12 15V8 M18 15V4',
    plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',down:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',
    check:'m5 12 4 4L19 6',chevron:'m9 5 7 7-7 7',clock:'M12 7v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',
    spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z M20 2v4 M18 4h4',
    link:'m9 15 6-6 M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0 M16 8l2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',
    menu:'M4 6h16 M4 12h16 M4 18h16',close:'M6 6l12 12 M18 6 6 18',folder:'M3 6h7l2 3h9v11H3V6Z',
    info:'M12 11v6 M12 7v.5 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',file:'M14 3H5v18h14V8l-5-5Z M14 3v6h5 M8 13h8 M8 16h6',
    external:'M14 3h7v7 M21 3 10 14 M10 3H3v18h18v-7',wallet:'M3 6h17v14H3V6Z M3 6l15-3v3 M15 11h7v5h-7v-5Z',trash:'M3 6h18 M8 6V3h8v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7'
  };
  const icon=(name,cls='')=>`<svg class='${cls}' aria-hidden='true' width='18' height='18' viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='1.65' stroke-linecap='round' stroke-linejoin='round'><path d='${paths[name]||paths.file}'/></svg>`;
  const btn=(text,action,classes='',ic='')=>`<button type='button' class='btn ${classes}' data-action='${action}'>${ic?icon(ic):''}${text}</button>`;
  const badge=(text,color='')=>`<span class='badge ${color}'>${text}</span>`;
  const stageName=a=>a.policy?'保障已确认':a.stage==='quoted'?'待客户确认':a.stage==='submitted'?'待核保':'投保草稿';
  function heading(kicker,title,desc,actions=''){return `<div class='page-heading'><h1>${title}</h1><div class='heading-actions'>${actions}</div></div>`;}
  function strip(){const a=app();return `<div class='case-strip'><span class='provider'>${esc(a.company.slice(0,1))}</span><span class='case-name'>${esc(a.company)}</span><span class='mono'>${esc(a.id)}</span><div class='right'><div class='state-steps'><b>投保</b><i>—</i><${a.quote?'b':'span'}>报价</${a.quote?'b':'span'}><i>—</i><${a.policy?'b':'span'}>出单</${a.policy?'b':'span'}><i>—</i><${a.claim.submitted?'b':'span'}>报案</${a.claim.submitted?'b':'span'}></div>${badge(stageName(a),a.policy?'green':'orange')}</div></div>`;}
  function card(title,subtitle,body,right='',classes=''){return `<section class='card ${classes}'><div class='card-head'><div><h2>${title}</h2></div>${right}</div>${body}</section>`;}
  const body=(html,cls='')=>`<div class='card-body ${cls}'>${html}</div>`;
  const stat=(label,value,note,ic='shield')=>`<article class='stat'><div class='stat-top'>${label}${icon(ic)}</div><div class='stat-value number'>${value}</div><div class='stat-note'>${note}</div></article>`;
  function field(label,path,value,type='text',note='',attrs=''){return `<label class='field'><span>${label}</span><input type='${type}' ${path} value='${esc(value)}' ${attrs}>${note?`<small>${note}</small>`:''}</label>`;}
  function select(label,path,value,options,note=''){return `<label class='field'><span>${label}</span><select ${path}>${options.map(x=>{const v=Array.isArray(x)?x[0]:x,t=Array.isArray(x)?x[1]:x;return `<option value='${esc(v)}' ${v===value?'selected':''}>${esc(t)}</option>`;}).join('')}</select>${note?`<small>${note}</small>`:''}</label>`;}
  function textarea(label,path,value,note=''){return `<label class='field wide'><span>${label}</span><textarea ${path}>${esc(value)}</textarea>${note?`<small>${note}</small>`:''}</label>`;}
  const kv=(label,value)=>`<div class='key-value'><span>${label}</span><strong>${value}</strong></div>`;
  function lockedNote(){return app().policy?`<div class='note green locked-banner'>${icon('shield')} 该保单已按报价快照确认，承保参数已锁定。${btn('复制为新的投保单','clone-app','small')}</div>`:'';}
  function sidebar(){const items=[['application','form','承保','客户 · 投保问卷'],['underwriting','globe','核保','保险人 · 风险与报价'],['claim','claim','理赔','客户 · 事故申报'],['assessment','scan','核赔','保险人 · 调查与结案'],['model','model','定价模型','演示参数 · 版本管理']];
    $('#sidebar').innerHTML=`<div class='sidebar-brand'><img class='brand-icon' src='icon.svg' alt=''><div><strong>CloudBridge</strong><small>Digital Resilience Insurance</small></div></div><div class='sidebar-scroll'><button class='sidebar-new' data-action='new-app'>${icon('plus')}新建投保单<kbd>＋</kbd></button><div class='section-label'>保险业务工作区 <span class='count'>05</span></div><nav>${items.map((x,i)=>`<button class='nav-item ${ui.view===x[0]?'active':''}' data-view='${x[0]}' ${ui.view===x[0]?"aria-current='page'":''}>${icon(x[1],'nav-icon')}<span><strong>${x[2]}</strong><small>${x[3]}</small></span><span class='step-no'>0${i+1}</span></button>`).join('')}</nav><div class='section-label'>演示投保单 <span class='count'>${state.apps.length}</span></div>${state.apps.map(a=>`<button class='app-entry ${a.id===app().id?'active':''}' data-select='${a.id}'><span class='app-avatar'>${esc(a.company.slice(0,1)||'新')}</span><span><strong>${esc(a.company||'未命名企业')}</strong><small>${a.services[0]?.kind==='AI API'?'AI API · ':''}${stageName(a)}</small></span>${a.policy?"<span class='app-dot'></span>":''}</button>`).join('')}<div class='section-label'>演示工具</div><button class='nav-item' data-action='guide'>${icon('info','nav-icon')}<span><strong>全流程演示导览</strong></span></button><button class='nav-item' data-action='load-case'>${icon('folder','nav-icon')}<span><strong>载入已承保样例</strong></span></button><button class='nav-item' data-action='export-workspace'>${icon('down','nav-icon')}<span><strong>导出业务档案</strong></span></button></div><div class='sidebar-bottom'><span class='avatar'>演</span><span>双端演示工作台<small>客户视角 + 保险人视角</small></span>${icon('shield')}</div>`;
  }
  function topbar(){const titles={application:'承保 · 投保问卷',underwriting:'核保工作台',claim:'理赔 · 事故申报',assessment:'核赔工作台',model:'定价模型'};$('#topbar').innerHTML=`<div class='breadcrumb'><button class='icon-btn mobile-menu' data-action='menu' aria-label='展开导航'>${icon('menu')}</button>${icon('folder')}<span>保险业务</span><span>/</span><strong>${titles[ui.view]}</strong></div><div class='top-tools'><span class='top-demo'><span class='dot'></span>双端演示</span><span class='divider'></span><button class='text-btn' data-action='guide'>演示导览 ↗</button><button class='icon-btn' data-action='about' aria-label='关于演示与数据来源'>${icon('info')}</button></div>`;}
  function render(){window.CBSelectUI.close();state.view=ui.view;sidebar();topbar();const map={application:applicationView,underwriting:underwritingView,claim:claimView,assessment:assessmentView,model:modelView};$('#main').innerHTML=`<div class='view-enter'>${map[ui.view]()}</div>`;window.CBSelectUI.enhance($('#main'));save();}
  function go(view,tab){ui.view=view;if(tab){if(view==='underwriting')ui.uwTab=tab;if(view==='assessment')ui.reviewTab=tab;}render();window.scrollTo({top:0,behavior:'instant'});$('#sidebar').classList.remove('open');$('#scrim').classList.remove('show');}
  function worldMap(){
    if(ui.mapModule==='m2')return window.CBM2Map.render(app(),state.model,ui);
    const a=app(),r=D.regions.find(x=>x.id===(ui.region||a.services[0].region)),mode=ui.mapModule,geo=window.CBWorldMap;
    const probability=region=>state.model.regionOverrides?.[region.id]?.[mode]??region[mode];
    const colors=p=>mode==='m1'?(p<19?'#668a76':p<24?'#bd9652':'#bc7160'):(p<1?'#668a76':p<3?'#bd9652':'#bc7160');
    const offsets={'us-east':[0,-31],'eu-west':[0,-31],singapore:[-18,39],japan:[36,-27],'middle-east':[0,-31],australia:[-35,39],brazil:[-8,39]};
    return `<div class='map-toolbar'><div class='segmented' aria-label='风险模块'><button class='${mode==='m1'?'active':''}' data-map='m1'>M1 日常中断</button><button class='${mode==='m2'?'active':''}' data-map='m2'>M2 冲突外溢</button></div><span class='muted'>年度事件概率 · 演示假设</span></div>
    <div class='world-map real-world-map'><div class='map-caption'><span>云服务区域</span><span>07 个观察区域</span></div><svg viewBox='0 0 960 480' role='group' aria-label='基于真实海岸线的全球云区域风险地图，可选择七个区域；概率为演示假设'>
    <defs><linearGradient id='map-ocean' x1='0' y1='0' x2='0' y2='1'><stop offset='0' stop-color='#f6f9fd'/><stop offset='1' stop-color='#edf2f8'/></linearGradient><linearGradient id='map-land' x1='0' y1='0' x2='0' y2='1'><stop offset='0' stop-color='#e3e7ec'/><stop offset='1' stop-color='#d4dce5'/></linearGradient></defs>
    <path d='${geo.sphere}' fill='url(#map-ocean)' stroke='#e2e8f0' stroke-width='1'/><path class='geo-grid' d='${geo.graticule}'/><path class='geo-land' d='${geo.land}'/>
    <g class='ocean-labels' aria-hidden='true'><text x='185' y='280'>太 平 洋</text><text x='433' y='250'>大 西 洋</text><text x='620' y='310'>印 度 洋</text></g>
    ${D.regions.map(region=>{const p=probability(region),c=colors(p),selected=region.id===r.id,[x,y]=geo.points[region.id],[dx,dy]=offsets[region.id],label=region.name,w=label.length*18+26;return `<g class='map-pin geo-pin ${selected?'selected':''}' data-region='${region.id}' role='button' tabindex='0' aria-pressed='${selected}' aria-label='${region.name} ${mode} 演示年度概率${p}%' style='color:${c}'><title>${label} · ${region.code} · ${mode.toUpperCase()} ${pct(p)}（演示）</title><circle class='halo' cx='${x}' cy='${y}' r='${selected?22:15}' fill='${c}'/><circle class='pin-ring' cx='${x}' cy='${y}' r='${selected?11:8}' fill='#ffffff' stroke='${c}' stroke-width='1.5'/><circle cx='${x}' cy='${y}' r='${selected?6:4.5}' fill='${c}'/><path class='pin-leader' d='M${x},${y+(dy>0?13:-13)} L${x+dx},${y+dy+(dy>0?-15:9)}'/><rect class='pin-label-bg' x='${x+dx-w/2}' y='${y+dy-18}' width='${w}' height='29' rx='6'/><text class='pin-label' x='${x+dx}' y='${y+dy+2}' text-anchor='middle'>${label}</text></g>`;}).join('')}</svg><div class='map-attribution'>Natural Earth 海岸线 · 区域代表位置</div></div>
    <div class='map-legend'><span><i class='dot' style='color:#668a76'></i>较低</span><span><i class='dot' style='color:#bd9652'></i>中等</span><span><i class='dot' style='color:#bc7160'></i>较高</span><span style='margin-left:auto'>点击标记查看风险</span></div>
    <div class='region-summary'><div><div class='place'>${r.name} ${badge(r.code,'')}</div><small>${r.id===a.services[0].region?'当前投保所在区域':'当前地图选中区域'} · ${r.country}</small></div><div><small>M1 年度事件概率</small><strong>${pct(state.model.regionOverrides?.[r.id]?.m1??r.m1)}</strong></div><div><small>M2 年度事件概率</small><strong class='amber'>${pct(state.model.regionOverrides?.[r.id]?.m2??r.m2)}</strong></div></div>`;
  }
  function quoteCard(){const a=app(),q=a.policy?.quote||a.quote||quote();return card(ui.mapModule==='m2'&&ui.view==='underwriting'&&ui.uwTab==='risk'?'投保单报价 · 原模型':'报价试算','',body(`<div class='demo-stamp'>${esc(q.modelVersion)} · 演示费率</div><div class='quote-price number'><small>¥</small>${money(q.total)}<span class='unit'>/ 年</span></div><p class='quote-meta'>${a.m2?'双模块保障':'M1单模块'} · ${a.services.length}项列明服务 · 人民币</p><div class='price-row'><span><i class='dot' style='color:#397aad'></i> M1 日常数字中断</span><strong>¥ ${money(q.p1)}</strong></div><div class='price-row'><span><i class='dot' style='color:#94a3b8'></i> M2 第三国冲突外溢</span><strong>${a.m2?'¥ '+money(q.p2):'未选择'}</strong></div><div class='mini-bar'><span class='m1' style='width:${q.total?q.p1/q.total*100:100}%'></span><span class='m2' style='width:${q.total?q.p2/q.total*100:0}%'></span></div><div class='quote-divider'></div><div class='price-row'><span>每小时约定金额</span><strong>¥ ${money(q.hourly)}</strong></div><div class='price-row'><span>等待期 / 最长赔偿</span><strong>${a.waiting}分钟 <small>/</small> ${a.maxHours}小时</strong></div><div class='price-row'><span>共同事故限额</span><strong>¥ ${integer(a.occLimit)}</strong></div><div class='quote-divider'></div>${a.policy?btn('查看已确认演示保单','policy-tab','primary full','shield'):a.stage==='quoted'?btn('客户确认报价与保障','confirm-policy','primary full','check'):btn('审核并生成报价','approve-quote','primary full','arrow')}`),'','quote-card');}
  function serviceTable(){const a=app();return card('列明服务与业务依赖','核保时锁定服务、区域及独立业务组',`<div class='table-wrap'><table><thead><tr><th>云服务 / 业务</th><th>承保区域</th><th>业务连续性</th><th class='num'>每小时金额</th><th></th></tr></thead><tbody>${a.services.map(s=>`<tr><td><div class='cell-flex'><span class='provider'>${esc(s.provider.slice(0,1))}</span><span><strong>${esc(s.provider)} · ${esc(s.service)}</strong><small>${esc(s.group)} · ${esc(s.business)}</small></span></div></td><td>${esc(D.regions.find(r=>r.id===s.region)?.code)}</td><td>${badge(s.backup==='tested'?'备用已演练':s.backup==='untested'?'备用未验证':'暂无可用替代',s.backup==='tested'?'green':'orange')}</td><td class='num'>¥ ${money(E.hourly(s))}</td><td><button class='text-btn' data-action='edit-services'>详情 ↗</button></td></tr>`).join('')}</tbody></table></div><div class='card-foot'><span>同一业务多项依赖须合并核定，避免重复承保损失。</span><button class='text-btn' data-action='edit-services'>编辑依赖清单 →</button></div>`);}
  function eventsCard(){return card('历史事件与风险证据','真实公开事件仅作参考，不直接转换为事故概率',`<div class='event-list'>${D.events.map(x=>`<article class='event-item'><time class='event-date'>${x.date}</time><div><h3>${x.title}${badge(x.module)}</h3><p>${x.summary}</p><a href='${x.url}' target='_blank' rel='noopener noreferrer'>${x.source} ↗</a></div></article>`).join('')}</div>`);}
  function underwritingView(){const a=app(),q=a.policy?.quote||a.quote||quote();const tabs=[['risk','风险总览'],['pricing','定价明细'],['approval','核保审查'],['policy','报价与保单']];return heading('','核保工作台','',btn('导出核保摘要','export-underwriting','','down')+btn(a.policy?'查看演示保单':'核保审查',a.policy?'policy-tab':'approval-tab','dark','arrow'))+strip()+`<div class='tabs'>${tabs.map(x=>`<button data-uwtab='${x[0]}' class='${ui.uwTab===x[0]?'active':''}'>${x[1]}${x[0]==='risk'?'<small>01</small>':''}</button>`).join('')}</div>`+(ui.uwTab==='risk'?`<div class='stats'>${stat('约定小时金额',`¥ ${integer(q.hourly)}`,'业务量 × 贡献毛利 × 不可挽回比例','wallet')}${stat('每次事故限额',`¥ ${integer(a.occLimit)}`,'同因事故、多项服务共用限额','shield')}${stat('年度总限额',`¥ ${integer(a.annualTotal)}`,'M1与M2共同受总限额约束','model')}${stat('当前承保依赖',`${a.services.length}<small>项服务</small>`,`${new Set(a.services.map(s=>s.group)).size} 个独立业务组 · ${a.calendar==='business'?'工作日09–17':'全天营业'}`,'link')}</div><div class='content-grid ${ui.mapModule==='m2'?'m2-expanded':''}'><div class='stack'>${card('全球风险视图','双模块、分区域风险观察',worldMap(),`<button class='text-btn' data-action='risk-method'>口径与来源 ↗</button>`,'risk-map-card')}${serviceTable()}</div><div class='stack'>${quoteCard()}<div class='insight'><div class='insight-icon'>${icon('spark')}</div><div><h3>待核实事项 ${badge('规则演示')}</h3><p>${a.services.some(s=>s.backup!=='tested')?'当前存在未经验证的替代方案，建议补充切换演练记录，核实关键业务是否真正恢复。':'备用方案已有演练记录；仍需核查备用服务与主服务是否共享上游故障点。'}</p><button class='text-btn' data-action='dependency-insight'>查看依赖分析 →</button></div></div>${card('保障结构','两类事故，统一限额管理',body(kv('M1 普通数字服务中断',badge('已选择','green'))+kv('M2 第三国物理冲突外溢',badge(a.m2?'已选择':'未选择',a.m2?'orange':''))+kv('M1 / M2年度限额',`${integer(a.annual1)} / ${integer(a.annual2)}元`)+kv('赔款封顶','承保净损失声明及各项限额')))}</div></div><div class='bottom-grid'>${eventsCard()}${card('核保检查摘要','从投保数据生成的审查线索',body(`<ul class='review-checklist'><li><span>${icon('check')}服务及区域列明</span>${badge('已识别','green')}</li><li><span>${icon('check')}业务量与毛利依据</span>${badge('待人工核验','orange')}</li><li><span>${icon('check')}独立业务组去重</span>${badge(E.validateApplication(a).some(x=>x.includes('重复业务'))?'待处理':'已检查','green')}</li><li><span>${icon('check')}跨区替代演练</span>${badge(a.services.every(s=>s.backup==='tested')?'已提供':'需关注','orange')}</li></ul><div class='mt'>${btn('进入核保审查','approval-tab','full','arrow')}</div>`))}</div>`:ui.uwTab==='pricing'?pricingView():ui.uwTab==='approval'?approvalView():policyView());}
  function pricingView(){const a=app(),q=a.policy?.quote||a.quote||quote();return `<div class='content-grid'><div class='stack'>${card('小时金额核定','以可解释的业务数据确定，不按云服务商总收入分摊',`<div class='table-wrap'><table><thead><tr><th>业务组</th><th class='num'>业务量/小时</th><th class='num'>单笔贡献毛利</th><th class='num'>不可挽回比例</th><th class='num'>小时金额</th></tr></thead><tbody>${a.services.map(s=>`<tr><td>${esc(s.group)}<small>${esc(s.business)}</small></td><td class='num'>${s.volume}</td><td class='num'>¥ ${money(s.margin)}</td><td class='num'>${s.irrecoverable}%</td><td class='num'>¥ ${money(E.hourly(s))}</td></tr>`).join('')}</tbody></table></div><div class='card-foot'>失败重试按唯一任务去重；能够补做的收入不计为永久损失。</div>`)}${card('双模块保费计算','模型为演示近似；生产定价需经精算验证和正式审批',`<div class='table-wrap'><table><thead><tr><th>服务 / 区域</th><th class='num'>M1纯保费</th><th class='num'>M2纯保费</th><th class='num'>年毛保费</th></tr></thead><tbody>${q.rows.map(r=>`<tr><td>${esc(a.services.find(s=>s.id===r.id)?.service)}<small>${r.region.name} · M1 ${pct(r.m1p*100)} / M2 ${pct(r.m2p*100)}</small></td><td class='num'>${money(r.pure1)}</td><td class='num'>${money(r.pure2)}</td><td class='num'>${money(r.premium1+r.premium2)}</td></tr>`).join('')}<tr><td><strong>合计</strong></td><td class='num'>${money(q.pure1)}</td><td class='num'>${money(q.pure2)}</td><td class='num'><strong>¥ ${money(q.total)}</strong></td></tr></tbody></table></div>`)}${card('计算口径','输入可追溯，公式由确定性计算引擎执行',body(`<div class='formula'>λ = −ln(1 − 年度至少一次事件概率)<br>M1纯保费 = λ₁ × 单次示例损失 × 业务影响系数 × 厂商系数 × 备用系数<br>M2纯保费 = λ₂ × 单次示例损失 × 业务影响系数 × (1 + 相关性附加) × 备用系数<br><strong>年毛保费 = (M1纯保费 + M2纯保费) × (1 + 风险附加) ÷ (1 − 费用率)</strong></div><div class='mt'>${btn('查看模型参数与版本','go-model','','model')}</div>`))}</div><div class='stack'>${quoteCard()}${card('本次参数快照','保单确认后固定对应版本',body(kv('模型版本',q.modelVersion)+kv('M1 / M2示例总中断时长',`${a.policy?.model.duration1??state.model.duration1}h / ${a.policy?.model.duration2??state.model.duration2}h`)+kv('业务受影响系数',pct(a.policy?.model.businessImpact??state.model.businessImpact))+kv('风险附加 / 费用率',`${a.policy?.model.riskLoad??state.model.riskLoad}% / ${a.policy?.model.expense??state.model.expense}%`)+kv('历史事件用途','辅助审查，不直接推出概率')))}</div></div>`;}
  function applicationView(){const a=app(),steps=['企业信息','服务清单','业务连续性','财务影响','保障条件','确认提交'],disabled=a.policy?'disabled':'';let form='';
    if(ui.formStep===0)form=`<div class='form-grid'>${field('被保险人企业名称 *',`data-a='company' ${disabled}`,a.company)}${select('所属行业',`data-a='industry' ${disabled}`,a.industry,['跨境电商','AI应用服务','跨境SaaS','数字营销','其他'])}${field('统一社会信用代码 / 注册编号',`data-a='registration' ${disabled}`,a.registration,'text','')}${field('授权联系人 *',`data-a='contact' ${disabled}`,a.contact)}${field('联系邮箱 *',`data-a='email' ${disabled}`,a.email,'email')}${select('营业时间口径',`data-a='calendar' ${disabled}`,a.calendar,[['business','工作日 09:00–17:00'],['24x7','全年 7×24 小时']],'')}</div>`;
    if(ui.formStep===1)form=a.services.map((s,i)=>`<section class='service-box'><div class='box-head'><h3>${s.id} · 列明服务</h3>${!a.policy&&a.services.length>1?`<button class='icon-btn' data-remove-service='${i}' aria-label='删除服务${i+1}'>${icon('trash')}</button>`:badge('服务依赖')}</div><div class='form-grid'>${select('云服务厂商 *',`data-s='${i}.provider' ${disabled}`,s.provider,['Azure','AWS','Google Cloud','Cloudflare','其他'])}${select('服务类型 *',`data-s='${i}.kind' ${disabled}`,s.kind,['云计算','云存储','数据库','AI API','CDN / 网络','其他'])}${field('具体产品 / 服务 *',`data-s='${i}.service' ${disabled}`,s.service)}${select('部署区域 *',`data-s='${i}.region' ${disabled}`,s.region,D.regions.map(r=>[r.id,r.name+' · '+r.code]))}${field('模型 / 部署端点 / 功能边界',`data-s='${i}.endpoint' ${disabled}`,s.endpoint,'text',s.kind==='AI API'?'列明模型和部署端点；质量下降、幻觉不视为可用性中断':'生产数据面、网络或读写功能须明确')}${field('独立业务组编号 *',`data-s='${i}.group' ${disabled}`,s.group,'text','同一业务的多项依赖须先合并核定')}${field('用于哪项业务 *',`data-s='${i}.business' ${disabled}`,s.business)}${field('该服务每次事故限额（元）',`data-s='${i}.limit' ${disabled}`,s.limit,'number','','min=1 step=10000')}${textarea('业务依赖与关键交易说明',`data-s='${i}.dependency' ${disabled}`,s.dependency)}</div></section>`).join('')+(!a.policy?btn('添加另一独立业务的服务','add-service','','plus'):'');
    if(ui.formStep===2)form=a.services.map((s,i)=>`<section class='service-box'><div class='box-head'><h3>${s.id} · ${esc(s.service)}</h3>${badge(s.backup==='tested'?'已演练':'需关注',s.backup==='tested'?'green':'orange')}</div><div class='form-grid'>${select('替代 / 备份可用性',`data-s='${i}.backup' ${disabled}`,s.backup,[['none','没有可用替代'],['untested','有替代，但尚未完成演练'],['tested','已完成业务切换演练']])}${field('目标恢复时间RTO（分钟）',`data-s='${i}.rto' ${disabled}`,s.rto,'number','','min=0 max=10080')}${field('最近一次切换演练日期',`data-s='${i}.backupDate' ${disabled}`,s.backupDate,'date',s.backup==='tested'?'已演练状态必须提供日期':'可在核保时补充')}${select('主备是否共用关键上游',`data-s='${i}.sharedDependency' ${disabled}`,s.sharedDependency||'unknown',[['unknown','待核查'],['yes','存在共用上游'],['no','已验证无共用故障点']])}${textarea('替代方案、演练结果及数据恢复说明',`data-s='${i}.backupNotes' ${disabled}`,s.backupNotes||'','区分备份数据存在、服务能启动与关键业务真正恢复。')}</div></section>`).join('');
    if(ui.formStep===3)form=a.services.map((s,i)=>`<section class='service-box'><div class='box-head'><h3>${esc(s.group)} · ${esc(s.business)}</h3>${badge('小时金额依据')}</div><div class='form-grid'>${field('正常业务量（唯一付费任务/小时） *',`data-s='${i}.volume' ${disabled}`,s.volume,'number','按订单或付费任务去重，不使用API请求次数。','min=1 step=1')}${field('每笔贡献毛利（元） *',`data-s='${i}.margin' ${disabled}`,s.margin,'number','收入扣除随业务发生的可变成本。','min=0.01 step=0.01')}${field('不可挽回比例（%） *',`data-s='${i}.irrecoverable' ${disabled}`,s.irrecoverable,'number','恢复后能够补做并取得收入的部分应剔除。','min=0.01 max=100 step=1')}${field('财务依据观察期',`data-s='${i}.basisPeriod' ${disabled}`,s.basisPeriod||'近90天同营业时段','text')}${textarea('数据来源与估算依据',`data-s='${i}.financialBasis' ${disabled}`,s.financialBasis||'业务系统按唯一订单汇总，财务核对单笔贡献毛利；根据历史补单率估计不可挽回比例。')}</div><div class='formula mt'>${integer(s.volume)} 笔/小时 × ¥${money(s.margin)} × ${s.irrecoverable}%<br><strong>建议约定小时金额：¥ ${money(E.hourly(s))}</strong></div></section>`).join('');
    if(ui.formStep===4)form=`<div class='form-grid'>${field('保险起始日期 *',`data-a='periodStart' ${disabled}`,a.periodStart,'date')}${field('保险终止日期 *',`data-a='periodEnd' ${disabled}`,a.periodEnd,'date','终止日00:00不再属于保障期间')}${field('等待期（分钟）',`data-a='waiting' ${disabled}`,a.waiting,'number','同一合并事故累计实际中断时间扣除一次。','min=0 max=1440 step=5')}${field('最长可赔时间（小时）',`data-a='maxHours' ${disabled}`,a.maxHours,'number','仅累计符合营业时间和业务影响的可赔分钟。','min=0.1 max=168 step=0.5')}${field('共同每次事故限额（元）',`data-a='occLimit' ${disabled}`,a.occLimit,'number','','min=1 step=10000')}${field('M1年度累计限额（元）',`data-a='annual1' ${disabled}`,a.annual1,'number','','min=1 step=10000')}${select('是否投保M2扩展',`data-a='m2' data-bool ${disabled}`,a.m2?'true':'false',[['true','投保 · 第三国物理冲突外溢'],['false','不投保 · 仅M1']])}${field('M2年度累计限额（元）',`data-a='annual2' ${disabled}`,a.annual2,'number','','min=1 step=10000')}${field('保单年度总限额（元）',`data-a='annualTotal' ${disabled}`,a.annualTotal,'number','','min=1 step=10000')}</div><div class='coverage-list'><article><h3>M1 普通中断</h3><p>约定的硬件、软件、操作、供电及网络故障等。仍适用具体责任边界和除外约定。</p></article><article><h3>M2 物理冲突外溢</h3><p>限约定物理事件影响非直接交战国设施而引发的服务中断。纯网络事件不自动归入M2。</p></article></div>`;
    if(ui.formStep===5){const errors=E.validateApplication(a);form=`${kv('投保企业',esc(a.company))}${kv('服务与独立业务组',`${a.services.length}项服务 / ${new Set(a.services.map(x=>x.group)).size}个业务组`)}${kv('约定小时金额合计','¥ '+money(quote().hourly))}${kv('保障期间',`${a.periodStart} 至 ${a.periodEnd}`)}${kv('等待期 / 最长可赔时间',`${a.waiting}分钟 / ${a.maxHours}小时`)}${kv('试算年保费','¥ '+money(quote().total))}<div class='note ${errors.length?'red':'green'} mt'>${errors.length?`提交前请处理：<ul class='error-list'>${errors.map(x=>`<li>${x}</li>`).join('')}</ul>`:'问卷检查通过'}</div><label class='check mt'><input type='checkbox' data-a='consent' ${a.consent?'checked':''} ${disabled}><span>我确认投保信息完整、准确，并已阅读保障条件。</span></label>`;}
    return heading('','承保 · 客户投保问卷','',btn('保存草稿','save-draft','','file')+btn('核保工作台','go-underwriting','dark','arrow'))+strip()+lockedNote()+`<div class='form-stepper'>${steps.map((x,i)=>`<button data-formstep='${i}' class='${ui.formStep===i?'active':''}'><span>${i+1}</span>${x}</button>`).join('')}</div><div class='content-grid single-column form-workspace'><div>${card(steps[ui.formStep],`第 ${ui.formStep+1} 步 / 共 6 步 · 客户可填写`,body(form,'padded'))}<div class='form-actions'><div>${ui.formStep?btn('上一步','form-prev'):''}${ui.formStep<5?btn('下一步','form-next','primary','arrow'):a.policy?btn('查看演示保单','policy-tab','primary','shield'):btn('提交投保问卷','submit-application','primary','check')}</div></div></div></div>`;
  }
  const uwItems=[['identity','企业与授权信息一致','核对投保主体、联系人及声明权限。'],['scope','服务依赖与备用方案已复核','服务、区域、端点、独立业务组和切换能力明确。'],['financial','小时金额与财务基础合理','业务量、贡献毛利和不可挽回比例有支持依据。'],['limits','保障边界与限额配置已复核','已解释等待期、净损失封顶、M2适用条件和除外事项。']];
  function approvalView(){const a=app(),errors=E.validateApplication(a);return `<div class='content-grid'><div class='stack'>${card('核保人工复核','规则检查形成线索，由演示核保人确认',body(`${errors.length?`<div class='note red mb'><strong>投保信息尚有问题</strong><ul class='error-list'>${errors.map(x=>`<li>${x}</li>`).join('')}</ul></div>`:''}${uwItems.map(([id,title,desc])=>`<div class='approval-item'><label class='check'><input type='checkbox' data-uwcheck='${id}' ${(a.uwChecks||[]).includes(id)?'checked':''} ${a.policy?'disabled':''}><span><h3>${title}</h3><p>${desc}</p></span></label></div>`).join('')}${textarea('核保意见与附加条件',`data-a='uwNote' ${a.policy?'disabled':''}`,a.uwNote||'建议出单前锁定服务及业务依赖清单；客户确认财务口径和未验证备用方案。')}<div class='form-actions'>${a.policy?btn('查看已确认保单','policy-tab','primary'):btn('确认复核并生成报价','approve-quote','primary','check')}</div>`,'padded'))}${card('自动检查记录','可解释的规则输出',body(kv('基础字段',errors.length?badge('需补充','orange'):badge('通过','green'))+kv('业务组重复',new Set(a.services.map(s=>s.group)).size===a.services.length?badge('未发现','green'):badge('转人工合并','orange'))+kv('AI API损失口径',a.services.some(s=>s.kind==='AI API')?'核查付费任务与补做，不按请求数':'本单非AI API业务')+kv('相关性与累计暴露','年度限额尚未做完整分布校准')+kv('定价模型',state.model.version+' · 仅演示')))}</div><div class='stack'>${quoteCard()}${card('业务轨迹','本浏览器的操作审计',body(historyView(a.history)))}</div></div>`;}
  function historyView(items){return `<div class='timeline audit-list'>${items.slice(0,20).map(x=>`<div class='timeline-entry'><time>${esc(x.at)}</time><p>${esc(x.text)}</p></div>`).join('')}</div>`;}
  function policyDocument(){const a=app(),q=a.policy?.quote||a.quote||quote(),t=a.policy?.terms||a;return `<div class='document-preview'><div class='doc-brand'>CLOUDBRIDGE / DIGITAL RESILIENCE</div><h2>${a.policy?'演示保险凭证':'演示报价单'}</h2><div class='doc-meta'>${esc(a.policy?.id||'QUOTE-'+a.id)} · ${esc(q.modelVersion)}</div>${kv('被保险人',esc(t.company))}${kv('保险期间',`${t.periodStart} 00:00 — ${t.periodEnd} 00:00（北京时间，终点不含）`)}${kv('保障模块',t.m2?'M1普通数字中断 + M2第三国物理冲突外溢':'M1普通数字服务中断')}${kv('年毛保费','¥ '+money(q.total))}${kv('等待期 / 最长可赔',`${t.waiting}分钟 / ${t.maxHours}小时`)}${kv('共同事故限额 / 年总限额',`¥${integer(t.occLimit)} / ¥${integer(t.annualTotal)}`)}${kv('M1 / M2年度限额',`¥${integer(t.annual1)} / ¥${integer(t.annual2)}`)}<h3>列明服务附表</h3><div class='table-wrap'><table><thead><tr><th>服务 / 端点</th><th>区域 / 业务组</th><th class='num'>小时金额</th></tr></thead><tbody>${t.services.map(s=>`<tr><td>${esc(s.provider)} · ${esc(s.service)}<small>${esc(s.endpoint)}</small></td><td>${D.regions.find(r=>r.id===s.region).code}<small>${esc(s.group)}</small></td><td class='num'>¥ ${money(E.hourly(s))}</td></tr>`).join('')}</tbody></table></div><h3>责任与计算口径摘要</h3><p>按约定阈值确认服务中断，并核实列明业务实际受影响。扣等待期后，仅累计营业时段与业务影响的交集；成功切换后停止累计。恢复后30分钟内再次中断按规则合并，中间正常时段不计入赔偿。</p><p>最终赔款受承保净损失声明、服务和共同事故限额、模块年度及总年度剩余额度约束；同一损失不重复补偿。M2须证明约定物理事件、非直接交战国设施与中断的因果链；纯网络事件不自动适用M2。</p><p>当前不含声誉损失、一般业务波动及未投保额外费用扩展。</p><div class='signature'><span>演示核保人：已授权角色<br>报价时间：${esc(a.quoteAt||'待核保')}</span><span>客户确认：${a.policy?'已模拟确认':'待确认'}<br>版本状态：${a.policy?'已锁定快照':'未生效报价'}</span></div></div>`;}
  function policyView(){const a=app();if(!a.quote&&!a.policy)return card('报价与保单','完成核保复核后生成',`<div class='empty'><div class='empty-icon'>${icon('file')}</div><h2>这份投保单还没有报价</h2><p>先完成客户问卷和核保审查，再由客户确认模拟报价并锁定保障。</p>${btn('进入核保审查','approval-tab','primary','arrow')}</div>`);return `<div class='content-grid'><div>${a.policy?`<div class='status-banner'>${icon('shield')}<div><strong>演示保障已确认 · 保单快照已锁定</strong><small>${a.policy.id} · ${a.policy.confirmedAt}</small></div></div>`:''}${policyDocument()}<div class='download-row'>${btn('下载报价 / 保单HTML','download-policy','','down')}${a.policy?btn('进入客户报案','go-claim','primary','arrow'):btn('客户确认报价与保障','confirm-policy','primary','check')}</div></div><div class='stack'>${quoteCard()}${card('确认与留痕','报价、客户确认与保障快照',body(historyView(a.history)))}</div></div>`;}
  function noPolicy(){return heading('','理赔与核赔','')+strip()+card('需要先确认演示保单','投保信息、报价和核赔使用同一份业务档案',`<div class='empty'><div class='empty-icon'>${icon('shield')}</div><h2>当前投保单尚未确认保障</h2><p>可继续核保并确认报价，也可以载入已经承保的完整样例，直接演示事故申报和保险人核赔。</p><div class='tag-row' style='justify-content:center'>${btn('继续核保','approval-tab','primary','arrow')}${btn('载入已承保样例','load-case','','folder')}</div></div>`);}
  function claimView(){if(!app().policy)return noPolicy();const c=claim(),t=policyTerms(),disabled=c.approved||c.paid?'disabled':'';return heading('','理赔 · 客户事故申报','',btn('下载事故报告','download-claim','','down')+btn('保险人核赔','go-assessment','dark','arrow'))+strip()+`${c.submitted?`<div class='status-banner'>${icon('check')}<div><strong>${c.paid?'案件已模拟支付结案':c.approved?'赔款已审核，等待模拟付款':'事故申报已收到 · 进入核赔调查'}</strong><small>${c.id} · ${c.submittedAt}</small></div></div>`:''}<div class='tabs'><button data-claimtab='report' class='${ui.claimTab==='report'?'active':''}'>事故报告</button><button data-claimtab='loss' class='${ui.claimTab==='loss'?'active':''}'>损失与减损</button><button data-claimtab='materials' class='${ui.claimTab==='materials'?'active':''}'>材料与声明</button></div><div class='content-grid single-column form-workspace'><div class='stack'>${ui.claimTab==='report'?card('事故基本信息','客户无需等待服务商根因报告即可报案',body(`<div class='form-grid'>${select('受影响的列明服务',`data-c='serviceId' ${disabled}`,c.serviceId,t.services.map(s=>[s.id,`${s.provider} · ${s.service} / ${s.group}`]))}${select('客户报告的事故线索',`data-c='reportedCause' ${disabled}`,c.reportedCause||(c.module==='m2'?'physical':'ordinary'),[['ordinary','普通服务故障 / 网络异常'],['physical','物理事件影响设施'],['unknown','原因尚不清楚']],'')}</div><div class='mini-title'>服务中断区间（北京时间）</div>${c.segments.map((s,i)=>`<div class='seg-row'>${field('中断起点',`data-seg='${i}.start' ${disabled}`,s.start,'datetime-local')}${field('服务恢复时间',`data-seg='${i}.end' ${disabled}`,s.end,'datetime-local')}${c.segments.length>1?`<button class='icon-btn' data-remove-seg='${i}' ${disabled} aria-label='删除区间${i+1}'>${icon('trash')}</button>`:'<span></span>'}</div>`).join('')}${!disabled?btn('添加再次中断区间','add-segment','small','plus'):''}<div class='form-grid mt'>${field('承保业务开始受影响',`data-c='impactStart' ${disabled}`,c.impactStart,'datetime-local')}${field('承保业务最终恢复',`data-c='impactEnd' ${disabled}`,c.impactEnd,'datetime-local')}${textarea('事故经过与当前情况 *',`data-c='description' ${disabled}`,c.description,'')}</div>`,'padded')):ui.claimTab==='loss'?card('损失、切换与恢复','将技术恢复与业务恢复分别记录',body(`<div class='form-grid'>${select('是否尝试替代、切换或补做',`data-c='attempted' data-bool ${disabled}`,c.attempted?'true':'false',[['true','已尝试'],['false','尚未尝试']])}${select('备用服务是否成功恢复业务',`data-c='switched' data-bool ${disabled}`,c.switched?'true':'false',[['false','未成功接管'],['true','已成功接管']])}${c.switched?field('切换后关键业务恢复时刻',`data-c='switchTime' ${disabled}`,c.switchTime,'datetime-local','成功恢复后的时间不再累计赔偿。'):''}${textarea('防损减损措施与结果',`data-c='measures' ${disabled}`,c.measures)}${textarea('服务及业务恢复记录',`data-c='recovery' ${disabled}`,c.recovery)}${field('最终无法挽回的任务数（参考）',`data-c='lostTasks' ${disabled}`,c.lostTasks,'number','','min=0 step=1')}${field('每笔贡献毛利（元，参考）',`data-c='taskMargin' ${disabled}`,c.taskMargin,'number','','min=0 step=0.01')}${field('声明承保净损失（元） *',`data-c='declaredLoss' ${disabled}`,c.declaredLoss,'number','扣除节省的可变成本；不要直接使用营业收入。','min=0 step=0.01')}${field('针对同一损失的其他补偿（元）',`data-c='otherCompensation' ${disabled}`,c.otherCompensation,'number','与该损失无关的云抵用券不自动全额冲减。','min=0 step=0.01')}${textarea('财务声明计算依据 *',`data-c='financialBasis' ${disabled}`,c.financialBasis)}</div><div class='note mt'>参考任务毛利：${integer(c.lostTasks)} × ¥${money(c.taskMargin)} = ¥${money(c.lostTasks*c.taskMargin)}</div>`,'padded')):card('索赔材料与授权声明','现有保单由保险人内部调取，不重复要求客户提供',body(`${evidenceList(false)}<div class='mini-title'>补充附件 · 本地演示</div><label class='field'><span>附件名称登记</span><input type='file' id='claim-files' multiple accept='.pdf,.docx,.xlsx,.csv,.json,.txt,.png,.jpg' ${disabled}></label><ul class='upload-list'>${c.uploads.map((f,i)=>`<li><span>${esc(f.name)} · ${(f.size/1024).toFixed(1)} KB</span><button class='text-btn' data-remove-upload='${i}' ${disabled}>移除</button></li>`).join('')}</ul><div class='form-grid mt'>${field('授权财务声明人',`data-c='financeSigner' ${disabled}`,c.financeSigner||'陈晓 · 示例授权财务人员')}${field('对公收款账户（演示脱敏）',`data-c='account' ${disabled}`,c.account)}</div><label class='check mt'><input type='checkbox' data-c='declaration' ${c.declaration?'checked':''} ${disabled}><span>我确认已按授权声明本次承保净损失，说明可补做任务与其他补偿；后续取得同一损失补偿时将继续披露。</span></label>`,'padded'))}<div class='form-actions'><div>${btn('保存事故草稿','save-claim','','file')}${!disabled?btn(c.submitted?'更新事故申报':'提交事故申报','submit-claim','primary','arrow'):btn('查看核赔结果','go-assessment','primary','arrow')}</div></div></div></div>`;}
  const evidenceDefs=[['E01','独立监测记录','保险人 / 监测机构 · 示例探测原始记录'],['E02','服务商故障说明','服务商公告或工单 · 可后补根因'],['E03','业务交易与恢复记录','客户技术部门 · 唯一任务及成功率'],['E04','切换与减损记录','客户运营 / 技术 · 是否真正恢复业务'],['E05','授权财务损失声明','客户财务 · 净损失与其他补偿'],['E07','授权与企业收款账户','客户提供 · 示例对公账户校验']];
  function evidenceList(review){const c=claim();return evidenceDefs.map(([id,title,desc])=>`<div class='evidence-row'><span class='evidence-id'>${id}</span><span class='copy'><strong>${title}</strong><small>${desc}</small></span>${review?`<label class='check'><input type='checkbox' data-verify='${id}' ${(c.checked||[]).includes(id)?'checked':''} ${!c.evidence[id]||c.approved?'disabled':''}>已核验</label>`:id==='E01'||id==='E02'?badge(c.evidence[id]?'演示已归档':'待取得',c.evidence[id]?'green':'orange'):id==='E05'?badge(c.declaration?'声明已确认':'待声明',c.declaration?'green':'orange'):`<label class='check'><input type='checkbox' data-evidence='${id}' ${c.evidence[id]?'checked':''} ${c.approved?'disabled':''}>模拟提供</label>`}</div>`).join('')+`<div class='evidence-row'><span class='evidence-id'>E06</span><span class='copy'><strong>保单及核保快照</strong><small>保险人内部调取 · ${esc(app().policy?.id||'暂无保单')}</small></span>${badge('内部已有','green')}</div>`;}
  function monitorChart(){const c=claim(),s=c.segments[0],start=E.stamp(s.start),end=E.stamp(s.end);if(!Number.isFinite(start)||!Number.isFinite(end)||end<=start)return `<div class='note red'>请先填写有效事故时间。</div>`;const span=Math.min(end-start+20,1440),a=start-10;let lines='';['#778e66','#b7a46f','#8bada4'].forEach((color,k)=>{const points=Array.from({length:61},(_,i)=>{const t=a+span*i/60,fail=c.segments.some(x=>t>=E.stamp(x.start)&&t<E.stamp(x.end)),y=fail?29+k*4+Math.sin(i*1.8+k)*4:141-k*3+Math.sin(i+k)*2;return `${50+i*9.6},${y}`;}).join(' ');lines+=`<polyline fill='none' stroke='${color}' stroke-width='1.8' points='${points}'/>`;});const tick=i=>new Date((a+span*i/4)*60000).toISOString().slice(11,16);return `<svg class='chart' viewBox='0 0 660 205' role='img' aria-label='三节点失败率模拟曲线'><g class='chart-grid'><path d='M50 25h580M50 85h580M50 145h580'/></g><path d='M50 85h580' stroke='#c7b57e' stroke-dasharray='4 4'/><g class='chart-label'><text x='7' y='29'>100%</text><text x='13' y='89'>50%</text><text x='19' y='149'>0%</text>${[0,1,2,3,4].map(i=>`<text x='${50+i*144}' y='179' text-anchor='middle'>${tick(i)}</text>`).join('')}<text x='54' y='199'>${esc(s.start.slice(0,10))} · 北京时间</text><text x='630' y='78' text-anchor='end'>中断判定线 50%</text></g>${lines}</svg>`;}
  function assessmentView(){if(!app().policy)return noPolicy();const a=app(),c=claim(),r=assessment(),t=policyTerms(),tabs=[['monitor','事故监测'],['evidence','材料与调查'],['liability','责任认定'],['calculation','赔款计算'],['closure','结案材料']];let panel='';
    if(ui.reviewTab==='monitor')panel=`<div class='content-grid single-column'><div class='stack'>${card('事故监测回放','模拟三节点探测 · 生产数据面 / 关键交易',body(`${monitorChart()}<div class='map-legend' style='padding:5px 0 15px'><span><i class='dot' style='color:#778e66'></i>节点A</span><span><i class='dot' style='color:#b7a46f'></i>节点B</span><span><i class='dot' style='color:#8bada4'></i>节点C</span><span style='margin-left:auto'>${badge(c.playback?'回放已生成':'待回放')}</span></div><small class='muted'>模拟监测</small><div class='download-row'>${btn(c.playback?'重新生成回放':'生成模拟监测回放','play-monitor','','scan')}${btn('证据预检','run-precheck','','scan')}</div>`))}${card('监测与业务时段对照','告警确认时刻不等于中断起点',body(kv('填报中断区间',c.segments.map(s=>`${esc(s.start.replace('T',' '))} — ${esc(s.end.slice(11))}`).join('<br>'))+kv('业务受影响区间',`${esc(c.impactStart.replace('T',' '))} — ${esc(c.impactEnd.slice(11))}`)+kv('成功切换',c.switched?esc(c.switchTime.replace('T',' ')):'未成功恢复业务')+kv('合并事故组数',r.groupCount||0)+kv('可赔区间',r.groups.flatMap(g=>g.ranges).join('、')||'暂无符合条件的区间')))}</div></div>`;
    if(ui.reviewTab==='evidence')panel=`<div class='content-grid'><div class='stack'>${card('材料接收与核验','预置材料均为模拟，勾选表示演示核赔人已复核',body(evidenceList(true),'padded'))}${card('调查与补件记录','只补充与本案认定有关的必要材料',body(`${textarea('调查意见 / 材料一致性核对',`data-c='reviewNote' ${c.approved?'disabled':''}`,c.reviewNote)}<div class='mt'>${textarea('集中补件要求',`data-c='notes' ${c.approved?'disabled':''}`,c.notes,'客户侧可在申报材料页继续补充；本演示不自动发送邮件。')}</div><div class='form-actions'>${btn('生成补件通知','supplement-notice','','file')}${btn('进入责任认定','liability-tab','primary','arrow')}</div>`,'padded'))}</div><div class='stack'>${card('客户申报摘要','保险人收到的客户信息',body(kv('事故说明',esc(c.description))+kv('防损减损',esc(c.measures))+kv('恢复记录',esc(c.recovery))+kv('声明净损失','¥ '+money(c.declaredLoss))+kv('同一损失其他补偿','¥ '+money(c.otherCompensation))+kv('财务依据',esc(c.financialBasis))))}${card('材料来源边界','辅助工具不能替代事实验证',body(`<ul class='list-clean'><li>客户日志不能单独证明云服务商事故。</li><li>服务商公告未发布不自动拒赔。</li><li>缺失监测时启动约定替代证据机制。</li><li>时间一致是线索，因果关系需核实。</li><li>财务汇总可抽查，异常再定向调查。</li></ul>`))}</div></div>`;
    if(ui.reviewTab==='liability')panel=liabilityView();
    if(ui.reviewTab==='calculation')panel=calculationView();
    if(ui.reviewTab==='closure')panel=closureView();
    return heading('','核赔工作台','',btn('导出核赔档案','export-assessment','','down')+btn('赔款计算书','calculation-tab','dark','file'))+strip()+`${!c.submitted?`<div class='note mb'>当前为报案前预览。客户提交事故申报后，才能完成赔款审核与模拟付款。${btn('进入客户申报','go-claim','small')}</div>`:''}${c.paid?`<div class='status-banner'>${icon('check')}<div><strong>已模拟支付 ¥ ${money(c.settlement.amount)} · 案件已结案</strong></div></div>`:''}<div class='tabs'>${tabs.map(x=>`<button data-reviewtab='${x[0]}' class='${ui.reviewTab===x[0]?'active':''}'>${x[1]}</button>`).join('')}</div><div class='stats'>${stat('服务中断时间',`${integer(r.rawMinutes)}<small>分钟</small>`,'合并区间，剔除正常恢复间隔','clock')}${stat('可赔时间初算',`${integer(r.eligibleMinutes)}<small>分钟</small>`,`${t.waiting}分钟等待期 · ${t.calendar==='business'?'工作日09–17':'7×24'}`,'scan')}${stat('声明净损失',`¥ ${integer(r.netLoss||0)}`,'客户声明扣除同一损失其他补偿','wallet')}${stat(c.paid?'已模拟赔款':'本次赔款试算',`¥ ${money(r.amount)}`,c.module==='pending'?'分类未定，须继续调查':`${c.module.toUpperCase()} · ${c.approved?'已审核':'尚未认定责任'}`,'shield')}</div>${panel}`;
  }
  function liabilityView(){const c=claim(),t=policyTerms(),disabled=c.approved?'disabled':'';return `<div class='content-grid'><div class='stack'>${card('保险责任认定','由演示核赔人核实；AI仅整理证据和提示争议',body(`<div class='form-grid'>${select('本案责任分类',`data-c='module' ${disabled}`,c.module,[['m1','M1 · 普通数字服务中断'],['m2','M2 · 第三国物理冲突外溢'],['pending','责任归类尚待调查'],['excluded','拟不予赔付 · 需说明依据']])}${field('受影响设施所在国',`data-c='facilityCountry' ${disabled}`,c.facilityCountry||D.regions.find(r=>r.id===assessment().s.region).country)}</div><div class='coverage-list' style='grid-template-columns:1fr 1fr'><article><h3>M1认定重点</h3><p>云服务故障与承保业务受损相对应；检查适用原因及除外事实。纯网络事件不自动归入M2。</p></article><article><h3>M2认定重点</h3><p>约定物理事件影响非直接交战国设施；供电、网络、服务中断与业务损失具有完整因果链。</p></article></div>${c.module==='m2'?`<div class='note ${t.m2?'':'red'} mt'>${t.m2?'保单已选择M2扩展，但仍须完成下列事实调查。':'本保单未投保M2，不能以该模块支付赔款。'}</div><div class='mt'><label class='check'><input type='checkbox' data-c='physicalVerified' ${c.physicalVerified?'checked':''} ${disabled}>已取得约定物理事件及设施 / 电力 / 网络受损证据</label><label class='check mt'><input type='checkbox' data-c='countryVerified' ${c.countryVerified?'checked':''} ${disabled}>已核实设施所在国在对应期间为非直接交战国</label><label class='check mt'><input type='checkbox' data-c='causalVerified' ${c.causalVerified?'checked':''} ${disabled}>已核实物理事件 → 设施受损 → 服务中断 → 业务受损的因果链</label></div>`:''}${c.module==='pending'?`<label class='check mt'><input type='checkbox' data-c='bothCovered' ${c.bothCovered?'checked':''} ${disabled}>已确定在M1与M2任一分类下均属承保责任，仅模块分配尚未确定</label>`:''}<div class='mt'>${textarea('责任依据、调查结论与待核实事项',`data-c='liabilityNote' ${disabled}`,c.liabilityNote||'')}</div><label class='check mt'><input type='checkbox' data-c='liabilityConfirmed' ${c.liabilityConfirmed?'checked':''} ${disabled}>我作为演示核赔人，已复核本案责任事实、适用条款和争议部分；不以系统初算代替责任决定。</label><div class='form-actions'>${btn('生成赔款计算书','calculation-tab','primary','arrow')}</div>`,'padded'))}</div><div class='stack'>${card('责任证据链','从事故到业务损失的对应关系',body(`<div class='timeline'><div class='timeline-entry'><time>事故原因</time><p>${c.module==='m2'?'约定物理事件与设施受损':'约定服务故障或网络异常'}</p></div><div class='timeline-entry'><time>技术中断</time><p>列明服务、区域、端点及监测阈值</p></div><div class='timeline-entry'><time>业务影响</time><p>关键交易失败、切换及业务恢复</p></div><div class='timeline-entry'><time>财务损失</time><p>不可挽回业务与授权净损失声明</p></div></div>`))}${card('除外与争议审查','需要具体事实，不能只依赖关键词',body(`<ul class='list-clean'><li>客户自身配置、额度或账户问题应区分。</li><li>战争、制裁及行政停服按条款审查。</li><li>M2特别扩展与一般除外须衔接。</li><li>有明确承保部分时，争议部分另行调查。</li><li>同一损失、同一业务时段不重复赔付。</li></ul>`))}</div></div>`;}
  function claimIssues(){const a=app(),c=claim(),r=assessment(),issues=[...r.errors];if(!c.submitted)issues.push('客户尚未提交事故申报');if(!c.declaration)issues.push('尚未确认授权财务损失声明');const need=['E01','E03','E04','E05','E07'];const missing=need.filter(x=>!c.checked.includes(x));if(missing.length)issues.push('尚未核验必要材料：'+missing.join('、'));if(!c.liabilityConfirmed)issues.push('核赔人尚未确认责任事实');if(!c.liabilityNote?.trim())issues.push('请填写责任依据与调查结论');if(c.module==='m2'){if(!policyTerms().m2)issues.push('保单未选择M2');if(!c.physicalVerified||!c.countryVerified||!c.causalVerified)issues.push('M2物理事件、非直接交战国或因果链调查尚未完成');}if(c.module==='pending')issues.push('模块分配尚待调查，本演示不自动支付待分配款');if(c.module==='excluded')issues.push('当前为不予赔付意见，须形成有事实和条款依据的人工决定');if(r.groupCount>1)issues.push('本次申报含多个独立事故组，请人工分案后核定');if(r.rawMinutes===0)issues.push('事故时段不在保险期间');if(r.amount<=0)issues.push('当前无正的可支付金额，需说明计算与责任结论');return [...new Set(issues)];}
  function calculationDocument(){const a=app(),c=claim(),r=assessment(),t=policyTerms();return `<div class='document-preview'><div class='doc-brand'>CLOUDBRIDGE / CLAIM CALCULATION</div><h2>赔款计算书</h2><div class='doc-meta'>${esc(c.id)} · ${esc(a.policy.id)} · ${esc(a.policy.model.version)}</div><div class='tag-row mt'>${badge(c.module==='m1'?'M1 普通中断':c.module==='m2'?'M2 物理冲突外溢':c.module==='pending'?'模块待分配':'责任待人工决定',c.module==='m2'?'orange':'green')}${badge(c.approved?'已模拟审核':'调查阶段初算')}</div>${kv('被保险人',esc(a.company))}${kv('列明服务 / 区域',`${esc(r.s.provider)} · ${esc(r.s.service)} / ${D.regions.find(x=>x.id===r.s.region).code}`)}<div class='table-wrap'><table><thead><tr><th>计算项目</th><th>口径</th><th class='num'>结果</th></tr></thead><tbody><tr><td>实际服务中断</td><td>区间去重，剔除中间正常运行</td><td class='num'>${r.rawMinutes}分钟</td></tr><tr><td>等待期</td><td>每个合并事故累计扣一次</td><td class='num'>${t.waiting}分钟/事故</td></tr><tr><td>可赔时间</td><td>扣等待期 × 营业时间 × 业务影响；成功切换截断</td><td class='num'>${r.eligibleMinutes}分钟</td></tr><tr><td>约定小时金额</td><td>保单快照，核赔不重新议价</td><td class='num'>¥${money(r.hourly)}</td></tr><tr><td>参数计算金额</td><td>${money(r.hourly)} × ${r.eligibleMinutes} ÷ 60</td><td class='num'>¥${money(r.parameter)}</td></tr><tr><td>净损失封顶</td><td>声明损失 ${money(c.declaredLoss)} − 同损失补偿 ${money(c.otherCompensation)}</td><td class='num'>¥${money(r.netLoss)}</td></tr><tr><td>服务 / 共同事故限额</td><td>同因事故共同约束</td><td class='num'>${integer(r.s.limit)} / ${integer(t.occLimit)}</td></tr><tr><td>模块年度剩余</td><td>M1 / M2，支付前</td><td class='num'>${money(r.remaining1)} / ${money(r.remaining2)}</td></tr><tr><td>总年度剩余</td><td>支付前额度</td><td class='num'>¥${money(r.totalRemaining)}</td></tr><tr><td><strong>本次${c.approved?'核定':'试算'}赔款</strong></td><td>逐项取限，金额最终四舍五入到分</td><td class='num'><strong>¥${money(r.amount)}</strong></td></tr></tbody></table></div><h3>核赔意见</h3><p>${esc(c.reviewNote)}</p><p>${esc(c.liabilityNote||'责任认定尚待核赔人确认。')}</p><p>${r.groupCount>1?'存在多个独立事故，需人工分案。':''}同一损失不重复赔付；收到同损失补偿后须复核调整。</p><div class='signature'><span>核赔复核：${c.approved?'已模拟确认':'待复核'}<br>时间：${esc(c.approvedAt||'—')}</span><span>客户确认：${c.accepted?'已模拟确认':'待确认'}<br>付款：${c.paid?'已模拟支付':'未支付'}</span></div></div>`;}
  function calculationView(){const c=claim(),r=assessment(),issues=claimIssues();return `<div class='content-grid'><div>${calculationDocument()}<div class='download-row'>${btn('下载计算书HTML','download-calculation','','down')}${btn('下载计算明细CSV','download-calculation-csv','','down')}${c.approved?btn('查看结案材料','closure-tab','primary','arrow'):btn('复核并核定赔款','approve-claim','primary','check')}</div></div><div class='stack'>${card('双模块对照','同一事故仅归入适用模块，不重复叠加',body(`<div class='module-grid'><div class='module-card'><h3>M1 ${badge('普通中断','green')}</h3><p>若认定符合M1</p><div class='amount number'>¥${money(r.m1)}</div><small>${c.module==='m1'?'本次选定模块':'仅比较，不计入本次赔款'}</small></div><div class='module-card m2'><h3>M2 ${badge('物理外溢','orange')}</h3><p>${policyTerms().m2?'若认定符合M2':'当前未投保M2'}</p><div class='amount number'>¥${money(r.m2)}</div><small>${c.module==='m2'?'本次选定模块':'仅比较，不计入本次赔款'}</small></div></div>${c.module==='pending'&&c.bothCovered?`<div class='note mt'>两种归类下均确定应付的下限：¥${money(Math.min(r.m1,r.m2))}。本演示仅试算，不自动支付或结案。</div>`:''}`))}${card('付款前检查','必要材料与责任必须复核',body(issues.length?`<ul class='error-list'>${issues.map(x=>`<li>${x}</li>`).join('')}</ul><div class='mt'>${btn('补充核赔调查','evidence-tab','full','arrow')}</div>`:`<div class='note green'>必要检查已完成，可由授权核赔人进行模拟审批。</div>`))}${card('可赔时段明细','健康间隔不计入等待期和赔偿',body(r.groups.map((g,i)=>kv(`事故组${i+1}`,`${g.rawMinutes}分钟中断 / ${g.payable}分钟可赔<br>${g.ranges.join('、')||'无可赔区间'}`)).join('')))}</div></div>`;}
  function closureView(){const a=app(),c=claim(),r=assessment(),t=policyTerms();return `<div class='content-grid'><div class='stack'>${card('赔案结案与支付','赔款审核、客户确认、模拟支付依次留痕',body(`<div class='timeline'><div class='timeline-entry'><time>${esc(c.submittedAt||'待提交')}</time><p>客户事故申报 ${badge(c.submitted?'已完成':'待完成',c.submitted?'green':'')}</p></div><div class='timeline-entry'><time>${esc(c.approvedAt||'待核定')}</time><p>保险人核定赔款 ¥${money(r.amount)} ${badge(c.approved?'已完成':'待完成',c.approved?'green':'')}</p></div><div class='timeline-entry'><time>${esc(c.acceptedAt||'待客户确认')}</time><p>客户确认赔款及收款账户 ${badge(c.accepted?'已完成':'待完成',c.accepted?'green':'')}</p></div><div class='timeline-entry'><time>${esc(c.paidAt||'待支付')}</time><p>模拟支付与额度入账 ${badge(c.paid?'已完成':'待完成',c.paid?'green':'')}</p></div></div><div class='large-result'><div class='label'>本案${c.paid?'已模拟支付':'核定 / 试算'}金额</div><div class='value number'>¥ ${money(r.amount)}</div><small>${esc(c.account)}</small></div><div class='tag-row' style='justify-content:center'>${!c.approved?btn('先完成赔款审核','calculation-tab','primary','arrow'):!c.accepted?btn('客户确认赔款与账户','accept-settlement','primary','check'):!c.paid?btn('模拟支付并结案','pay-claim','primary','wallet'):badge('已结案','green')}</div>`,'padded'))}${card('结案档案清单','可下载计算书、报告与结构化归档',body(`<ul class='review-checklist'><li><span>${icon('file')}客户事故报告与损失声明</span>${btn('下载','download-claim','small')}</li><li><span>${icon('file')}赔款计算书</span>${btn('下载','download-calculation','small')}</li><li><span>${icon('file')}结案报告与支付演示凭证</span>${btn('下载','download-closure','small')}</li><li><span>${icon('file')}材料索引、操作轨迹及快照</span>${btn('导出JSON','export-assessment','small')}</li></ul>`))}</div><div class='stack'>${card('年度额度台账','模拟支付后才扣减；单次事故限额不永久减少',body(kv('M1年度剩余','¥ '+money(Math.max(0,t.annual1-a.paid.m1)))+kv('M2年度剩余','¥ '+money(Math.max(0,t.annual2-a.paid.m2)))+kv('保单年度总剩余','¥ '+money(Math.max(0,t.annualTotal-a.paid.total)))+kv('本次支付归属',c.paid?c.module.toUpperCase():'待支付')+kv('后续独立事故限额','仍按每次事故 ¥'+integer(t.occLimit))))}${card('案件操作轨迹','过程留痕，可追溯至业务档案',body(historyView(a.history)))}${card('演示处理时效','拟定服务标准，非真实机构承诺',body(kv('确认收到报案','1个工作日')+kv('集中提出补件','2个工作日')+kv('普通案件资料齐备后核定','5个工作日')+kv('达成赔偿协议后付款','5个自然日')))}</div></div>`;}
  function modelView(){const m=state.draftModel,a=app(),active=quote(a,state.model),draft=quote(a,m);const params=[['duration1','M1示例事故总中断时长',.1,168,.1,'小时'],['duration2','M2示例事故总中断时长',.1,168,.1,'小时'],['businessImpact','事件影响承保业务的系数',1,100,1,'%'],['riskLoad','风险附加',0,100,1,'%'],['expense','费用率',0,90,1,'%'],['correlation','M2相关性附加',0,200,1,'%']];return heading('','定价模型与版本','',btn('导出模型参数','export-model','','down')+btn('模拟审批并生效','activate-model','dark','check'))+`<div class='model-status'>${badge(state.model.version,'blue')}<span>演示模型</span></div><div class='tabs'><button data-modeltab='parameters' class='${ui.modelTab==='parameters'?'active':''}'>模型参数</button><button data-modeltab='regions' class='${ui.modelTab==='regions'?'active':''}'>地区概率</button><button data-modeltab='sensitivity' class='${ui.modelTab==='sensitivity'?'active':''}'>敏感性试算</button><button data-modeltab='versions' class='${ui.modelTab==='versions'?'active':''}'>版本与审批</button></div><div class='model-layout'><div class='stack'>${ui.modelTab==='parameters'?card('演示模型参数','编辑后仅影响右侧草稿试算；需模拟审批后应用到新报价',body(params.map(([id,label,min,max,step,unit])=>`<label class='model-param'><span>${label}</span><input aria-label='${label}' type='number' data-m='${id}' value='${m[id]}' min='${min}' max='${max}' step='${step}'><small>${unit}</small></label>`).join('')+`<div class='formula mt'>λ = −ln(1 − p)<br>示例损失 = min[小时金额 × min(可赔上限, 示例时长 − 等待期), 服务限额, 事故限额]<br><strong>毛保费 = 双模块期望损失 × (1 + 风险附加) ÷ (1 − 费用率)</strong></div><details class='model-coefficients'><summary>查看演示系数</summary><p>厂商演示系数：Azure 1.00、AWS 0.95、Google Cloud 1.02、Cloudflare 1.08、其他1.15。备用已演练0.72、未演练0.90、无替代1.00。均为教学假设。</p></details><div class='form-actions'>${btn('还原未生效参数','reset-model-draft')}${btn('模拟审批并生效','activate-model','primary','check')}</div>`,'padded')):ui.modelTab==='regions'?card('地区年度事件概率','年度至少一次符合定义事件的假设概率；不等同于国家风险评级',`<div class='table-wrap'><table><thead><tr><th>区域</th><th class='num'>M1概率（%）</th><th class='num'>M2概率（%）</th></tr></thead><tbody>${D.regions.map(r=>`<tr><td><strong>${r.name}</strong><small>${r.code}</small></td><td><input type='number' aria-label='${r.name}M1概率' data-r='${r.id}.m1' min='0' max='99.9' step='.1' value='${m.regionOverrides?.[r.id]?.m1??r.m1}'></td><td><input type='number' aria-label='${r.name}M2概率' data-r='${r.id}.m2' min='0' max='99.9' step='.1' value='${m.regionOverrides?.[r.id]?.m2??r.m2}'></td></tr>`).join('')}</tbody></table></div><div class='card-foot'>生效后同步风险地图与未出单业务的报价；已确认保单不受影响。</div>`):ui.modelTab==='sensitivity'?sensitivityView():card('模型版本与模拟审批','每次生效形成一个新版本；历史保单保留原快照',body(historyView(state.modelHistory)+`<div class='mt'>${btn('模拟审批当前草稿','activate-model','primary','check')}</div>`,'padded'))}</div><div class='stack'>${card('当前投保单敏感性','草稿结果与演示生效版本比较',body(`<div class='demo-stamp'>${esc(a.company)}</div><div class='large-result'><div class='label'>草稿参数年毛保费</div><div class='value number'>¥ ${money(draft.total)}</div><small>当前版本：¥${money(active.total)}</small></div>${kv('与当前版本差额',`${draft.total-active.total>=0?'+':'−'} ¥${money(Math.abs(draft.total-active.total))}`)}${kv('草稿M1 / M2保费',`¥${money(draft.p1)} / ¥${money(draft.p2)}`)}${kv('当前生效模型',state.model.version)}${kv('客户已确认保单',a.policy?'保留 '+a.policy.model.version+' 快照':'尚未确认保障')}`))}</div></div>`;}
  function sensitivityView(){const a=app(),m=state.draftModel,scenarios=[['当前草稿',m,a],['M1时长增加50%',{...m,duration1:m.duration1*1.5},a],['M2时长增加50%',{...m,duration2:m.duration2*1.5},a],['所有备用完成演练',m,{...a,services:a.services.map(s=>({...s,backup:'tested'}))}],['不可挽回比例下降20%',m,{...a,services:a.services.map(s=>({...s,irrecoverable:s.irrecoverable*.8}))}]];const base=quote(a,m).total;return card('敏感性情景对比','只改变所列因素，其余输入保持一致',`<div class='table-wrap'><table><thead><tr><th>情景</th><th class='num'>年毛保费</th><th class='num'>相对草稿</th></tr></thead><tbody>${scenarios.map(([label,mm,aa])=>{const total=quote(aa,mm).total;return `<tr><td>${label}</td><td class='num'>¥${money(total)}</td><td class='num'>${base?((total/base-1)*100).toFixed(1):'0.0'}%</td></tr>`;}).join('')}</tbody></table></div>`);}
  function modal(title,content,footer=''){const d=$('#dialog');$('#dialog-content').innerHTML=`<div class='modal-head'><h2>${title}</h2><button class='icon-btn' data-action='close-dialog' aria-label='关闭弹窗'>${icon('close')}</button></div><div class='modal-body'>${content}</div><div class='modal-footer'>${footer||btn('知道了','close-dialog','primary')}</div>`;if(!d.open)d.showModal();}
  const closeModal=()=>$('#dialog').close();
  function errorModal(title,errors){modal(title,`<div class='note red'><ul class='error-list'>${errors.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`);}
  function termsSnapshot(a){const keys=['company','industry','contact','email','registration','periodStart','periodEnd','calendar','waiting','maxHours','occLimit','annual1','annual2','annualTotal','m2','services'];return Object.fromEntries(keys.map(k=>[k,clone(a[k])]));}
  function invalidateQuote(){const a=app();if(a.quote){a.quote=null;a.quoteModel=null;a.quoteAt=null;a.uwChecks=[];audit('投保资料变更 · 原演示报价作废，需重新核保');}a.stage='draft';}
  function confirmPolicy(){const a=app();if(a.policy)return toast('该演示保单已确认');if(!a.quote)return toast('请先完成核保并生成报价');a.policy={id:a.id.replace('CB-A','CB-P'),confirmedAt:now(),terms:termsSnapshot(a),quote:clone(a.quote),model:clone(a.quoteModel)};a.stage='bound';audit('客户模拟确认报价与保障 · 保单及模型快照锁定');save();closeModal();go('underwriting','policy');toast('保障已确认');}
  function newApplication(source=null){const a=source?clone(source):D.base();a.id='CB-A-'+Date.now().toString(36).toUpperCase();a.company=source?source.company+'（新投保）':'';a.stage='draft';a.quote=null;a.quoteModel=null;a.quoteAt=null;a.policy=null;a.uwChecks=[];a.paid={m1:0,m2:0,total:0};a.history=[{at:now(),text:source?'复制为新投保单，原保单不变':'新建投保草稿'}];a.consent=false;if(!source){a.contact='';a.email='';a.registration='';}a.claim=D.claim(a);a.claim.evidence={E01:false,E02:false,E03:false,E04:false,E05:false,E07:false};state.apps.unshift(a);state.selected=a.id;ui.formStep=0;ui.region=null;go('application');toast('新投保单已创建');}
  function loadCase(kind){const index=kind==='ai'?1:kind==='m2'?2:0;let a=state.apps.find(x=>x.sampleKind===kind);if(!a){a=clone(D.apps[index]);a.id='CB-A-DEMO-'+kind.toUpperCase();a.sampleKind=kind;a.quote=quote(a,state.model);a.quoteModel=clone(state.model);a.quoteAt=now();a.uwChecks=uwItems.map(x=>x[0]);a.policy={id:a.id.replace('CB-A','CB-P'),confirmedAt:now(),terms:termsSnapshot(a),quote:clone(a.quote),model:clone(state.model)};a.stage='bound';a.claim=D.claim(a);a.claim.module=kind==='m2'?'m2':'m1';a.claim.id=a.policy.id.replace('CB-P','CB-C');a.history.unshift({at:now(),text:'载入预置已承保演示样例'});state.apps.unshift(a);}state.selected=a.id;ui.region=null;closeModal();go('claim');toast('已载入演示保障，可填写事故、损失和声明');}
  function download(name,content,type='application/json'){const blob=new Blob([content],{type:type+';charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.style.display='none';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('文件已生成');}
  function downloadHTML(name,title,html){const css="body{font:14px/1.8 system-ui,'PingFang SC',sans-serif;color:#333;max-width:950px;margin:40px auto;padding:25px}h2{font-size:26px}h3{margin-top:25px}.key-value{display:flex;justify-content:space-between;gap:20px;border-bottom:1px solid #e5e5dd;padding:10px 0}.key-value strong{text-align:right;font-weight:500}.key-value span,small,.doc-meta,.signature{color:#888}table{width:100%;border-collapse:collapse;font-size:12px}td,th{padding:12px;text-align:left;border-bottom:1px solid #ddd}th{background:#f6f5ef}.num{text-align:right}td small{display:block}.note{padding:12px;background:#f5f3eb;margin:15px 0}.badge{background:#eff3e9;border-radius:4px;padding:3px 7px;font-size:11px}.signature{display:flex;justify-content:space-between;border-top:1px solid #ddd;padding-top:20px;margin-top:25px;font-size:12px}.tag-row{display:flex;gap:10px;margin:15px 0}.doc-brand{letter-spacing:2px;color:#6d8066;font-size:11px}.btn{display:none}@media print{body{margin:0;max-width:none}.note{border:1px solid #ddd}}";download(name+'.html',`<!DOCTYPE html><html lang='zh-CN'><meta charset='UTF-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>${esc(title)} · 演示文件</title><style>${css}</style><body>${html}<p style='font-size:10px;color:#999;margin-top:40px'>CloudBridge · ${esc(now())}</p></body></html>`,'text/html');}
  function incidentDocument(){const a=app(),c=claim();return `<div class='document-preview'><div class='doc-brand'>CLOUDBRIDGE / INCIDENT REPORT</div><h2>事故报告与损失声明</h2><div class='doc-meta'>${esc(c.id)} · 客户申报 ${c.submitted?'已提交':'草稿'}</div>${kv('投保企业',esc(a.company))}${kv('列明服务',esc(policyTerms().services.find(s=>s.id===c.serviceId)?.service||''))}${kv('服务中断',c.segments.map(s=>esc(s.start.replace('T',' ')+' 至 '+s.end.replace('T',' '))).join('<br>'))}${kv('业务受影响',esc(c.impactStart.replace('T',' ')+' 至 '+c.impactEnd.replace('T',' ')))}${kv('事故经过',esc(c.description))}${kv('切换 / 防损减损',esc(c.measures))}${kv('是否成功切换',c.switched?'是，'+esc(c.switchTime):'否')}${kv('恢复记录',esc(c.recovery))}${kv('声明净损失','¥'+money(c.declaredLoss))}${kv('同损失其他补偿','¥'+money(c.otherCompensation))}${kv('财务计算依据',esc(c.financialBasis))}${kv('授权声明',c.declaration?'已模拟确认':'尚未确认')}${kv('财务声明人',esc(c.financeSigner||a.contact))}<h3>材料索引</h3><p>${evidenceDefs.map(([id,name])=>`${id} ${name}：${c.evidence[id]?'演示已归档':'待补充'}`).join('<br>')}</p><h3>补充附件名称</h3><p>${c.uploads.map(x=>esc(x.name)).join('<br>')||'无'}</p></div>`;}
  function closureDocument(){const a=app(),c=claim(),r=assessment();return `<div class='document-preview'><div class='doc-brand'>CLOUDBRIDGE / CLOSING REPORT</div><h2>结案报告与支付演示凭证</h2><div class='note'>${c.paid?'已模拟支付':'草稿'}</div>${kv('案件 / 保单',esc(c.id+' / '+a.policy.id))}${kv('被保险人',esc(a.company))}${kv('责任模块',esc(c.module.toUpperCase()))}${kv('核定赔款','¥'+money(r.amount))}${kv('支付状态',c.paid?'已模拟支付':'尚未支付')}${kv('收款账户',esc(c.account))}${kv('支付时间',esc(c.paidAt||'—'))}${kv('M1 / M2已用额度',money(a.paid.m1)+' / '+money(a.paid.m2))}${kv('年度总剩余额度','¥'+money(policyTerms().annualTotal-a.paid.total))}<h3>责任与计算意见</h3><p>${esc(c.reviewNote)}</p><p>${esc(c.liabilityNote||'待补充')}</p><h3>案件操作记录</h3><p>${a.history.map(x=>esc(x.at+' '+x.text)).join('<br>')}</p><p>同一损失后续取得补偿须继续披露。收取无争议赔款不代表放弃争议部分。</p></div>`;}
  function exportAssessment(){const a=app();download(a.claim.id+'-核赔档案.json',JSON.stringify({demo:true,exportedAt:now(),policy:a.policy,claim:a.claim,calculation:a.policy?assessment():null,ledger:a.paid,audit:a.history},null,2));}
  function modelErrors(){const m=state.draftModel,errors=[];[['duration1',.1,168],['duration2',.1,168],['businessImpact',1,100],['riskLoad',0,100],['expense',0,90],['correlation',0,200]].forEach(([k,min,max])=>{if(!Number.isFinite(m[k])||m[k]<min||m[k]>max)errors.push(`${k}超出允许范围`);});Object.values(m.regionOverrides).forEach(r=>Object.values(r).forEach(p=>{if(!Number.isFinite(p)||p<0||p>99.9)errors.push('地区概率须处于0%至99.9%之间');}));return errors;}
  const actions={
    'close-dialog':closeModal,
    'menu':()=>{$('#sidebar').classList.toggle('open');$('#scrim').classList.toggle('show');},
    'guide':()=>modal('全流程演示导览',`<p>同一份业务档案在客户与保险人两端流转。可从问卷开始，也可载入已承保样例，直接演示赔案。</p><div class='guide-list'>${[['application','客户填写投保问卷','列明厂商、服务、业务依赖、备用方案和财务影响。'],['underwriting','保险人核保与报价','查看区域风险、历史事件、定价依据，完成复核。'],['claim','客户确认保障并报案','记录中断、切换、业务恢复和损失声明。'],['assessment','保险人调查与核赔','核验材料、认定M1/M2、生成计算书并模拟结案。'],['model','模型参数与审批','调整演示假设，比较敏感性并锁定版本。']].map((x,i)=>`<div class='guide-step'><span>${i+1}</span><div><strong>${x[1]}</strong><p>${x[2]}</p></div><button class='text-btn' data-guide-view='${x[0]}'>进入 →</button></div>`).join('')}</div>`,btn('载入已承保样例','load-case','','folder')+btn('从问卷开始','guide-start','primary','arrow')),
    'guide-start':()=>{closeModal();ui.formStep=0;go('application');},
    'about':()=>modal('关于这份演示工作台',`<p>CloudBridge · 跨境数字服务中断保险</p>`,btn('查看风险口径','risk-method')+btn('知道了','close-dialog','primary')),
    'm2-compare':()=>modal('M2 区域参考报价',window.CBM2Map.comparison(app(),state.model,ui),btn('关闭','close-dialog')),
    'risk-method':()=>ui.mapModule==='m2'?modal('M2 地图口径',`<p>三层分别展示源事件年概率、事件发生后的服务受影响概率、受影响后的中断与恢复。源事件概率不是赔付触发概率。</p><p>M2-SCENARIO-1.0 使用三类互斥源事件与三档时长假设；源事件按泊松过程计数，服务受影响按条件概率筛选。参数赔款按不可用时长扣除等待期，应用事故限额，并对全年多次事件累计应用年度限额。P90是服务受影响后的中断时长分位数。</p><p>所有区域概率、连接与恢复配置均为演示假设，不代表实时地缘态势或已验证的厂商架构。服务商名称来自投保单；同类服务使用相同情景系数，不对厂商作可靠性排名。图中连线只表示依赖关系。</p><p>综合风险按统一条件下的年均可赔小时分档：低于0.05小时为较低，0.05至不足0.2小时为中等，其余为较高。各图层颜色分别对应其图例。客户小时金额不改变风险等级。</p><p>参考报价独立于原模型，不写入已确认保单；M1、核赔及原报价流程保留原有计算规则。</p><p>底图：Natural Earth 1:50m 物理海岸线。区域点位为代表位置。</p>`,btn('关闭','close-dialog')):modal('风险地图与概率口径',`<p><strong>年度概率</strong>表示某区域在一年内至少发生一次符合示例定义事件的假设概率。模型以 λ = −ln(1−p) 转换为简化泊松频率，再结合示例严重度计算。</p><p><strong>风险颜色</strong>：M1低于19%为较低、19%至不足24%为中等、24%及以上为较高；M2低于1%为较低、1%至不足3%为中等、3%及以上为较高。阈值仅为演示，不是国家评级。</p><p><strong>M1与M2</strong>分别表示普通服务中断与约定物理冲突外溢。M2不是一般地缘风险兜底，须逐案核验非直接交战国设施及因果链。</p><p>真实历史事件只用于说明可能的故障机制，没有用三起事件外推出地区概率。底图采用 Natural Earth 1:50m 真实海岸线和 Natural Earth 投影；标记使用云区域代表城市附近的经纬度，不代表具体机房地址。底图为物理地理图，不绘制行政国界。<a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noopener noreferrer">地理数据来源与使用说明 ↗</a></p>`),
    'dependency-insight':()=>modal('服务依赖辅助分析 · 规则演示',`${app().services.map(s=>`<div class='approval-item'><h3>${esc(s.group)} · ${esc(s.business)}</h3><p>${esc(s.provider)} / ${esc(s.service)} / ${D.regions.find(r=>r.id===s.region).code}</p><p>依赖说明：${esc(s.dependency)}</p><p>小时金额依据：${s.volume} × ${s.margin} × ${s.irrecoverable}% = ¥${money(E.hourly(s))}</p><p>待核实：${s.backup==='tested'?'备用独立性、演练日志和实际恢复结果。':'可用替代方案、切换时长及实际业务恢复。'}</p></div>`).join('')}`),
    'new-app':()=>newApplication(),
    'clone-app':()=>newApplication(app()),
    'load-case':()=>modal('选择已承保演示样例',`<div class='guide-list'><div class='guide-step'><span>01</span><div><strong>M1 · 云计算中断</strong><p>Azure East US · 每小时2万元 · 样例可赔80分钟。</p></div><button class='btn small' data-action='load-m1'>载入</button></div><div class='guide-step'><span>02</span><div><strong>M2 · 第三国物理外溢</strong><p>新加坡设施假设情景 · 需核实非直接交战国与因果链。</p></div><button class='btn small' data-action='load-m2'>载入</button></div><div class='guide-step'><span>03</span><div><strong>AI API · 按次收费业务</strong><p>区分调用失败、重试补做和真正不可挽回的付费任务。</p></div><button class='btn small' data-action='load-ai'>载入</button></div></div>`),
    'load-m1':()=>loadCase('m1'),'load-m2':()=>loadCase('m2'),'load-ai':()=>loadCase('ai'),
    'go-underwriting':()=>go('underwriting'),'go-claim':()=>go('claim'),'go-assessment':()=>go('assessment'),'go-model':()=>go('model'),
    'approval-tab':()=>go('underwriting','approval'),'policy-tab':()=>go('underwriting','policy'),'calculation-tab':()=>go('assessment','calculation'),'closure-tab':()=>go('assessment','closure'),'evidence-tab':()=>go('assessment','evidence'),'liability-tab':()=>go('assessment','liability'),
    'edit-services':()=>{ui.formStep=1;go('application');},
    'save-draft':()=>{save();toast(app().policy?'已确认保单保持原快照':'草稿已保存');},
    'form-next':()=>{ui.formStep=Math.min(5,ui.formStep+1);render();window.scrollTo({top:0,behavior:'instant'});},
    'form-prev':()=>{ui.formStep=Math.max(0,ui.formStep-1);render();window.scrollTo({top:0,behavior:'instant'});},
    'add-service':()=>{if(app().policy)return;if(app().services.length>=8)return toast('演示最多列明8项服务');invalidateQuote();let n=1;while(app().services.some(s=>s.id==='SVC-'+String(n).padStart(2,'0')))n++;app().services.push({...clone(D.service),id:'SVC-'+String(n).padStart(2,'0'),group:'BIZ-'+String(n).padStart(2,'0'),business:'新的独立业务',service:'请填写具体服务'});render();toast('已添加服务，请确认其属于另一独立业务组');},
    'submit-application':()=>{const a=app();if(a.policy)return;const errors=E.validateApplication(a);if(!a.consent)errors.push('请在确认页勾选投保声明');if(errors.length){ui.formStep=5;render();return errorModal('投保问卷需要补充',errors);}a.stage='submitted';audit('客户提交投保问卷 · 等待核保');go('underwriting','approval');toast('问卷已提交，请演示保险人复核');},
    'approve-quote':()=>{const a=app();if(a.policy)return go('underwriting','policy');const errors=E.validateApplication(a);if(a.stage==='draft')errors.push('请先提交客户投保问卷');const missing=uwItems.filter(x=>!(a.uwChecks||[]).includes(x[0]));if(missing.length)errors.push('请逐项确认核保复核：'+missing.map(x=>x[1]).join('、'));if(errors.length){go('underwriting','approval');return errorModal('报价前需要完成核保复核',errors);}modal('确认生成演示报价',`<p>${esc(a.company)} · 约定小时金额 ¥${money(quote().hourly)}，试算年毛保费 ¥${money(quote().total)}。</p>`,btn('返回复核','close-dialog')+btn('确认生成报价','commit-quote','primary','check'));},
    'commit-quote':()=>{const a=app();a.quote=clone(quote());a.quoteModel=clone(state.model);a.quoteAt=now();a.stage='quoted';audit('演示核保人确认报价 · '+state.model.version+' · ¥'+money(a.quote.total));closeModal();go('underwriting','policy');toast('报价已生成，待客户确认保障');},
    'confirm-policy':()=>{const a=app();if(!a.quote)return toast('请先完成核保');modal('客户确认报价与保障',`<p>企业：${esc(a.company)}<br>保障期间：${a.periodStart} 至 ${a.periodEnd}<br>年毛保费：¥${money(a.quote.total)}<br>等待期：${a.waiting}分钟；最长可赔：${a.maxHours}小时。</p>`,btn('返回检查','close-dialog')+btn('模拟确认保障','commit-policy','primary','shield'));},
    'commit-policy':confirmPolicy,
    'save-claim':()=>{save();toast('事故草稿已保存');},
    'add-segment':()=>{const c=claim();if(c.approved)return;if(c.segments.length>=8)return toast('演示最多8个区间');c.segments.push({start:'2026-11-17T12:00',end:'2026-11-17T12:40'});c.submitted=false;c.checked=[];render();},
    'submit-claim':()=>{if(!app().policy)return;const c=claim();if(c.approved)return;const errors=E.assess(app(),c).errors;if(!c.description.trim())errors.push('请填写事故经过');if(errors.length)return errorModal('事故报告需要补充',errors);modal('提交客户事故申报',`<p>服务中断 ${assessment().rawMinutes} 分钟，声明净损失 ¥${money(c.declaredLoss)}。保险人将核实责任、业务影响和材料。</p><div class='note'>${c.declaration?'已确认财务损失声明。':'尚未确认财务声明，可先报案，核定赔款前须补充。'} </div>`,btn('继续填写','close-dialog')+btn('确认提交事故报告','commit-claim','primary','check'));},
    'commit-claim':()=>{const c=claim();c.submitted=true;c.submittedAt=now();c.evidence.E05=c.declaration;c.checked=[];c.liabilityConfirmed=false;audit('客户提交事故报告 · '+c.id+' · 声明损失¥'+money(c.declaredLoss));closeModal();go('assessment','monitor');toast('保险人已收到模拟报案');},
    'play-monitor':()=>{const c=claim();if(!c.approved){c.playback=true;c.evidence.E01=true;audit('生成E01模拟监测记录');}render();toast('监测回放已生成');},
    'run-precheck':()=>{const c=claim(),r=assessment();modal('证据辅助预检 · 本地规则演示',`${kv('服务中断 / 可赔分钟',r.rawMinutes+' / '+r.eligibleMinutes)}${kv('事故组数',r.groupCount||0)}${kv('成功切换',c.switched?'是，截断业务受影响时间':'无成功恢复记录')}${kv('待核验材料',evidenceDefs.filter(([id])=>!c.checked.includes(id)).map(x=>x[0]).join('、')||'无')}${kv('M2调查',c.module==='m2'?'核查设施国及完整物理因果链':'当前为M1或待分类')}${r.errors.length?`<div class='note red'>${r.errors.map(esc).join('<br>')}</div>`:''}`,btn('知道了','close-dialog')+btn('进入材料核验','precheck-evidence','primary','arrow'));},
    'precheck-evidence':()=>{closeModal();go('assessment','evidence');},
    'supplement-notice':()=>{const c=claim(),missing=evidenceDefs.filter(([id])=>!c.evidence[id]);const text=c.notes.trim()||('请补充或核实：'+(missing.length?missing.map(x=>x[0]+' '+x[1]).join('；'):'现有材料原始记录及关键时段一致性')+'。');c.notes=text;save();downloadHTML(c.id+'-补件通知','集中补件通知',`<h2>集中补件通知 · 演示</h2>${kv('案件',esc(c.id))}<p>${esc(text)}</p>`);render();},
    'approve-claim':()=>{const c=claim();if(c.approved)return toast('本案已核定');const issues=claimIssues();if(issues.length)return errorModal('核定赔款前需要完成',issues);modal('演示核赔人确认赔款',`<p>责任归属：${c.module.toUpperCase()}<br>核定赔款：¥${money(assessment().amount)}<br>收款主体：${esc(app().company)}</p>`,btn('返回检查','close-dialog')+btn('确认核定赔款','commit-approval','primary','check'));},
    'commit-approval':()=>{const c=claim();const issues=claimIssues();if(issues.length)return errorModal('仍有待处理事项',issues);const result=clone(E.assess(app(),c));c.settlement={amount:result.amount,module:c.module,assessment:result};c.approved=true;c.approvedAt=now();audit('核赔人模拟核定 '+c.module.toUpperCase()+' 赔款 ¥'+money(result.amount));closeModal();go('assessment','closure');toast('赔款已核定，待客户确认');},
    'accept-settlement':()=>{const c=claim();if(!c.approved)return toast('请先核定赔款');modal('客户确认赔款与账户',`<p>本次核定 ¥${money(c.settlement.amount)}，演示收款账户：${esc(c.account)}。</p>`,btn('返回','close-dialog')+btn('模拟客户确认','commit-acceptance','primary','check'));},
    'commit-acceptance':()=>{const c=claim();if(!c.approved)return;c.accepted=true;c.acceptedAt=now();audit('客户模拟确认赔款与对公收款账户');closeModal();render();toast('客户已模拟确认');},
    'pay-claim':()=>{const c=claim();if(!c.approved||!c.accepted)return toast('请先核定赔款并取得客户模拟确认');if(c.paid)return toast('本案已支付，不能重复入账');modal('模拟支付与结案',`<p>将模拟支付 ¥${money(c.settlement.amount)}，并扣减${c.module.toUpperCase()}及保单年度总剩余额度。</p>`,btn('返回检查','close-dialog')+btn('确认模拟支付','commit-payment','primary','wallet'));},
    'commit-payment':()=>{const a=app(),c=claim();if(!c.approved||!c.accepted||c.paid)return;const n=c.settlement.amount;a.paid[c.module]=E.round(a.paid[c.module]+n);a.paid.total=E.round(a.paid.total+n);c.paid=true;c.paidAt=now();audit('模拟支付结案 · '+c.module.toUpperCase()+' · ¥'+money(n)+'');closeModal();render();toast('已模拟支付并更新年度额度');},
    'reset-model-draft':()=>{state.draftModel=clone(state.model);render();toast('未生效参数已还原为当前演示版本');},
    'activate-model':()=>{const errors=modelErrors();if(errors.length)return errorModal('模型参数需要修正',errors);modal('模拟模型审批与版本生效',`<p>将由演示精算负责人确认新的演示参数版本。新参数应用于未出单业务；已有报价作废并重新核保，已确认保单保持原快照。</p>`,btn('返回试算','close-dialog')+btn('模拟审批并生效','commit-model','primary','check'));},
    'commit-model':()=>{if(modelErrors().length)return;const serial=state.modelHistory.length;state.model={...clone(state.draftModel),version:'DEMO-1.'+serial,activatedAt:now(),status:'演示生效'};state.draftModel=clone(state.model);state.modelHistory.unshift({at:now(),text:state.model.version+' · 演示精算负责人模拟审批生效'});state.apps.forEach(a=>{if(!a.policy&&a.quote){a.quote=null;a.quoteModel=null;a.uwChecks=[];a.stage='submitted';a.history.unshift({at:now(),text:'演示模型版本更新，原报价作废，需重新核保'});}});closeModal();render();toast('新演示版本已生效，已确认保单不受影响');},
    'export-workspace':()=>download('CloudBridge-业务档案.json',JSON.stringify({demo:true,exportedAt:now(),...state},null,2)),
    'export-model':()=>download(state.model.version+'-模型参数.json',JSON.stringify({demo:true,active:state.model,draft:state.draftModel,regions:D.regions,history:state.modelHistory},null,2)),
    'export-underwriting':()=>download(app().id+'-核保摘要.json',JSON.stringify({demo:true,application:termsSnapshot(app()),quote:app().policy?.quote||app().quote||quote(),model:app().policy?.model||app().quoteModel||state.model,review:app().uwChecks,notes:app().uwNote,audit:app().history},null,2)),
    'export-assessment':exportAssessment,
    'download-policy':()=>downloadHTML((app().policy?.id||app().id)+'-演示保单','报价与保险凭证',policyDocument()),
    'download-claim':()=>downloadHTML(claim().id+'-事故报告','事故报告与损失声明',incidentDocument()),
    'download-calculation':()=>downloadHTML(claim().id+'-赔款计算书','赔款计算书',calculationDocument()),
    'download-closure':()=>downloadHTML(claim().id+'-结案材料','结案报告',closureDocument()),
    'download-calculation-csv':()=>{const r=assessment(),rows=[['项目','数值','单位'],['服务中断时间',r.rawMinutes,'分钟'],['可赔时间',r.eligibleMinutes,'分钟'],['约定小时金额',r.hourly,'元/小时'],['参数计算金额',r.parameter,'元'],['净损失封顶',r.netLoss,'元'],['M1比较金额',r.m1,'元'],['M2比较金额',r.m2,'元'],['本次试算赔款',r.amount,'元']];download(claim().id+'-计算明细.csv','\uFEFF'+rows.map(x=>x.join(',')).join('\r\n'),'text/csv');}
  };
  document.addEventListener('click',event=>{const el=event.target.closest('button,a[data-action],g[data-region]');if(!el||el.disabled)return;
    if(el.dataset.action){const fn=actions[el.dataset.action];if(fn)fn();return;}
    if(el.dataset.view){go(el.dataset.view);return;}
    if(el.dataset.guideView){closeModal();go(el.dataset.guideView);return;}
    if(el.dataset.select){state.selected=el.dataset.select;ui.region=null;ui.m2Service=null;render();return;}
    if(el.dataset.uwtab){ui.uwTab=el.dataset.uwtab;render();return;}
    if(el.dataset.claimtab){ui.claimTab=el.dataset.claimtab;render();return;}
    if(el.dataset.reviewtab){ui.reviewTab=el.dataset.reviewtab;render();return;}
    if(el.dataset.modeltab){ui.modelTab=el.dataset.modeltab;render();return;}
    if(el.dataset.formstep!==undefined){ui.formStep=Number(el.dataset.formstep);render();return;}
    if(el.dataset.m2Layer){ui.m2Layer=el.dataset.m2Layer;render();document.querySelector(`[data-m2-layer='${ui.m2Layer}']`)?.focus({preventScroll:true});return;}
    if(el.dataset.map){ui.mapModule=el.dataset.map;render();return;}
    if(el.dataset.region){ui.region=el.dataset.region;render();document.querySelector(`.m2-region-switch [data-region='${ui.region}']`)?.focus({preventScroll:true});return;}
    if(el.dataset.removeService!==undefined&&!app().policy){invalidateQuote();app().services.splice(Number(el.dataset.removeService),1);if(!app().services.some(s=>s.id===claim().serviceId))claim().serviceId=app().services[0].id;render();return;}
    if(el.dataset.removeSeg!==undefined&&!claim().approved){claim().segments.splice(Number(el.dataset.removeSeg),1);claim().submitted=false;claim().checked=[];render();return;}
    if(el.dataset.removeUpload!==undefined&&!claim().approved){claim().uploads.splice(Number(el.dataset.removeUpload),1);render();}
  });
  function changedCustomerClaim(key){const customer=['serviceId','reportedCause','impactStart','impactEnd','attempted','switched','switchTime','measures','recovery','description','declaredLoss','otherCompensation','lostTasks','taskMargin','financialBasis','financeSigner','account','declaration'];if(!customer.includes(key))return;const c=claim();if(c.submitted){c.submitted=false;audit('客户申报信息变更 · 待重新提交');}c.checked=[];c.liabilityConfirmed=false;if(['declaredLoss','otherCompensation','financialBasis','lostTasks','taskMargin'].includes(key)){c.declaration=false;c.evidence.E05=false;}}
  function refreshPreviews(){
    const templates={application:applicationView,claim:claimView,model:modelView};
    if(!templates[ui.view])return;
    const fresh=document.createElement('div');fresh.innerHTML=templates[ui.view]();
    const selectors=ui.view==='model'?['.model-layout > .stack:last-child']:['.case-strip'];
    selectors.forEach(selector=>{const old=$('#main '+selector),updated=fresh.querySelector(selector);if(old&&updated)old.replaceWith(updated);});
    if(ui.view==='application'){
      const old=$$('#main .service-box .formula'),updated=[...fresh.querySelectorAll('.service-box .formula')];
      old.forEach((node,i)=>{if(updated[i])node.innerHTML=updated[i].innerHTML;});
    }
  }
  function handleField(event,typing=false){const el=event.target;if(!el.matches('input,select,textarea'))return;let val=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.hasAttribute('data-bool')?el.value==='true':el.value;
    if(el.type==='number'&&(!el.value||!Number.isFinite(val)||(el.min!==''&&val<Number(el.min))||(el.max!==''&&val>Number(el.max)))){if(!typing){toast('请输入允许范围内的有效数值');render();}return;}
    if(el.dataset.m2Option){const key=el.dataset.m2Option;if(!['m2Service','m2Basis','m2Configuration'].includes(key))return;ui[key]=val;if(key==='m2Service'){ui.region=(app().policy?.terms||app()).services.find(s=>s.id===val)?.region||null;}render();document.querySelector(`[data-m2-option='${key}']`)?.nextElementSibling?.focus({preventScroll:true});return;}
    const a=app(),c=claim();
    if(el.dataset.a){if(a.policy)return;const key=el.dataset.a;if(key!=='uwNote'){invalidateQuote();}a[key]=val;}
    else if(el.dataset.s){if(a.policy)return;invalidateQuote();const [i,key]=el.dataset.s.split('.');a.services[Number(i)][key]=val;}
    else if(el.dataset.c){if(c.approved)return;const key=el.dataset.c;changedCustomerClaim(key);c[key]=val;if(key==='declaration')c.evidence.E05=val;if(key==='module')c.liabilityConfirmed=false;}
    else if(el.dataset.seg){if(c.approved)return;const [i,key]=el.dataset.seg.split('.');c.segments[Number(i)][key]=val;c.submitted=false;c.checked=[];c.liabilityConfirmed=false;}
    else if(el.dataset.uwcheck){if(a.policy)return;a.uwChecks||=[];a.uwChecks=a.uwChecks.filter(x=>x!==el.dataset.uwcheck);if(val)a.uwChecks.push(el.dataset.uwcheck);}
    else if(el.dataset.verify){if(c.approved)return;c.checked=c.checked.filter(x=>x!==el.dataset.verify);if(val)c.checked.push(el.dataset.verify);}
    else if(el.dataset.evidence){if(c.approved)return;c.evidence[el.dataset.evidence]=val;c.checked=c.checked.filter(x=>x!==el.dataset.evidence);c.submitted=false;}
    else if(el.dataset.m){state.draftModel[el.dataset.m]=val;}
    else if(el.dataset.r){const [id,key]=el.dataset.r.split('.');state.draftModel.regionOverrides[id]||={};state.draftModel.regionOverrides[id][key]=val;}
    else if(el.id==='claim-files'){if(c.approved)return;c.uploads.push(...[...el.files].map(f=>({name:f.name,size:f.size,lastModified:f.lastModified})));c.submitted=false;c.checked=[];}
    else return;
    save();
    if(typing){refreshPreviews();return;}
    // Text edits are already synchronized on input. Keep the focused form intact
    // so a blur does not remove a button before its click can be delivered.
    if(el.matches('textarea,input:not([type=checkbox]):not([type=file])'))return;
    render();
  }
  document.addEventListener('input',event=>{if(event.target.matches('textarea,input:not([type=checkbox]):not([type=file])'))handleField(event,true);});
  document.addEventListener('change',event=>handleField(event,false));
  document.addEventListener('keydown',event=>{const layer=event.target.closest('[data-m2-layer]');if(layer&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const ids=['hazard','exposure','recovery'],i=ids.indexOf(ui.m2Layer);ui.m2Layer=event.key==='Home'?ids[0]:event.key==='End'?ids[2]:ids[(i+(event.key==='ArrowRight'?1:2))%3];render();document.querySelector(`[data-m2-layer='${ui.m2Layer}']`).focus({preventScroll:true});return;}const target=event.target.closest('g[data-region]');if(target&&(event.key==='Enter'||event.key===' ')){event.preventDefault();ui.region=target.dataset.region;render();document.querySelector(`g[data-region='${ui.region}']`)?.focus({preventScroll:true});}});
  $('#dialog').addEventListener('click',event=>{if(event.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
  $('#scrim').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#scrim').classList.remove('show');});
  window.addEventListener('storage',event=>{if(event.key===KEY&&event.newValue)toast('另一个标签页已更新档案，请刷新后继续，避免覆盖');});
  render();
})();
